INSERT INTO products (id, category_id, name, slug, short_description, description, brand, price, specs, stock_quantity, reserved_quantity, is_active, created_at, updated_at) OVERRIDING SYSTEM VALUE VALUES
	(1, 256, 'Áo cứu sinh coleman 364', 'ao-cuu-sinh-coleman-364', 'Áo cứu sinh coleman 364 làm bằng Polyester siêu nhẹ, chống thấm nước và giữ nhiệt rất tốt. Thiết kế áo có mũ trùm đầu tiện lợi, sử dụng khi gặp mưa hoặc thời tiết se lạnh khi đi du lịch, leo núi dã ngoại.', '<p><strong>Campvivo – Áo cứu sinh Coleman 364</strong></p> <div></div> <p><strong>Coleman là thương hiệu sản xuất <a href="/" rel="nofollow">đồ outdoor</a> nổi tiếng ra đời từ năm 1909. Với lịch sử hình thành và phát triển, Coleman đã khẳng định được vị trí thương hiệu của mình trong lòng khách hàng bởi chất lượng và sự tiện dụng của sản phẩm.</strong></p> <p><strong><img alt="Áo cứu sinh coleman 364" height="143" loading="lazy" src="https://wetrek.vn/pic/products/images/logo-coleman.jpg" width="400" /></strong></p> <p><a href="/products/ao-cuu-sinh-coleman-364" rel="nofollow">Áo cứu sinh Coleman 364</a> là một sản phẩm chính hãng <strong>Coleman</strong> được <strong>Campvivo </strong>phân phối.</p> <p><img alt="" height="500" loading="lazy" src="https://wetrek.vn/pic/products/images/ao-cuu-sinh-coleman.jpg" width="500" /></p> <p>Áo được làm bằng chất liệu Polyester siêu nhẹ, chống thấm nước, đồng thời có tác dụng giữ nhiệt cho bạn trong thời tiết se lạnh.<br /> <a href="/products/ao-cuu-sinh-coleman-364" rel="nofollow">Áo cứu sinh Coleman 364</a> được thiết kế như một chiếc áo không tay chui bình thường và có thêm mũ trùm đầu để giữ ấm cho cả đầu và tai bạn.<br /> Sau khi sử dụng, bạn có thể gấp áo lại và cho vào một chiếc túi nhỏ gọn tiết kiệm diện tích và khối lượng đồ bạn cần mang theo.<br /> <br /> Xem thêm chi tiết <a href="/products/dung-cu-cuu-sinh" rel="nofollow">Dụng cụ cứu sinh</a> tại <a href="/products/do-nam" rel="nofollow">ĐỒ NAM.</a></p>', 'COLEMAN', 59000, '[]'::jsonb, 50, 0, TRUE, '2026-10-23T17:14:10.609697+07:00', '2026-10-23T17:14:10.609697+07:00'),
	(2, 97, 'Áo bơi chống nắng ngắn tay nam Aqua Marina MIRAI MEN''S RASHGUARD SS-C-M18SS-NA', 'ao-boi-chong-nang-ngan-tay-nam-aqua-marina-mirai-men-s-rashguard-ss-c-m18ss-na-8373', 'Áo bơi chống nắng ngắn tay nam Aqua Marina MIRAI MEN''S RASHGUARD SS-C-M18SS-NA-8373 được thiết kế để bảo vệ người mặc khỏi những vết mẩn đỏ, trầy xước do bị chà xát, hoặc bị cháy nắng do da tiếp xúc với ánh nắng mặt trời trong thời gian dài. Người dùng có thể chỉ mặc riêng loại áo này hoặc mặc kết hợp bên trong bộ đồ bơi giữ nhiệt wetsuit, phù hợp cho các hoạt động như lướt sóng, chèo thuyền - kayak, chèo SUP, lướt ván buồn, lặn hay bơi lội.', '<p><strong>Campvivo</strong> lựa chọn và mang đến bạn sản phẩm <strong>Áo bơi chống nắng ngắn tay nam Aqua Marina MIRAI MEN&#39;S RASHGUARD C-M18SS-NA</strong></p> <p><img alt="Áo bơi chống nắng ngắn tay nam Aqua Marina MIRAI MEN&#39;S RASHGUARD SS-C-M18SS-NA" height="638" loading="lazy" src="https://wetrek.vn/pic/products/images/Ao-boi-chong-nang-ngan-tay-nam-mirai-men&#39;s-rashguard-ss-c-m18ss-na-campvivo-vn1.jpg" width="730" /></p> <p><img alt="Áo bơi chống nắng ngắn tay nam Aqua Marina MIRAI MEN&#39;S RASHGUARD SS-C-M18SS-NA" height="228" src="https://wetrek.vn/pic/Product/vuongkientoan.Campvivo&#64;gmail.com/images/Ao-boi-chong-nang-ngan-tay-nam-mirai-men&#39;s-rashguard-ss-c-m18ss-na-campvivo-vn2.jpg" width="730" /></p> <p>Áo bơi chống nắng <strong>Rashguard </strong>được thiết kế để bảo vệ người mặc khỏi những vết mẩn đỏ, trầy xước do bị chà xát, hoặc bị cháy nắng do da tiếp xúc với ánh nắng mặt trời trong thời gian dài. Người dùng có thể chỉ mặc riêng loại áo này hoặc mặc kết hợp bên trong bộ đồ bơi giữ nhiệt wetsuit, phù hợp cho các hoạt động như lướt sóng, chèo thuyền - kayak, chèo SUP, lướt ván buồn, lặn hay bơi lội.  <img alt="" src="https://wetrek.vn/pic/Product/vuongkientoan.Campvivo&#64;gmail.com/images/Ao-boi-chong-nang-ngan-tay-nam-mirai-men&#39;s-rashguard-ss-c-m18ss-na-campvivo-vn1.jpg" />Đặc điểm nổi bật sản phẩm <strong>Áo bơi chống nắng ngắn tay nam Aqua Marina MIRAI MEN&#39;S RASHGUARD C-M18SS-NA:</strong></p> <ul><li>Áo bơi chống nắng chất lượng cao mang lại sự linh hoạt tối đa cho người dùng</li><li>Đường may phẳng linh hoạt, nhẹ nhàng với da, không gây khó chịu cho da</li><li>Chống tia UV (UPF 50&#43;)</li><li>Cùng chất liệu vải thoáng khí khiến cho áo mau khô nhanh</li><li>Phần eo của áo siêu co giãn giúp dễ dàng mặc vào người</li></ul> <p><strong>Aqua Marina</strong> là một thương hiệu chuyên sản xuất các loại thuyền thể thao, thuyền bơm hơi, ván chèo đứng<strong> SUP</strong>, phụ kiện thuyền như bơm, mái chèo, túi khô. Được thành lập vào năm 2002<strong>, Aqua Marina</strong> đã chiếm thị phần lớn trong thị trường thuyền và ván chèo đứng bơm hơi toàn cầu bằng việc cung cấp các sản phẩm đa dạng, chất lượng cao, với giá cả phải chăng.</p> <p><img alt="Áo bơi chống nắng ngắn tay nam Aqua Marina MIRAI MEN&#39;S RASHGUARD SS-C-M18SS-NA" height="200" src="https://wetrek.vn/pic/Product/vuongkientoan.Campvivo&#64;gmail.com/images/1536126702.jpg" width="730" /></p>', 'AQUA MARINA', 925000, '[{"name": "Xuất xứ", "value": "Chính hãng"}, {"name": "Chất liệu", "value": "82% Polyester (vải chống nhăn/ thấm ) / 13% Spandex (Vải thun)"}, {"name": "Size", "value": "S / M / L /XL / XXL"}, {"name": "Hướng dẫn sử dụng", "value": "Giặt máy với nước lạnh"}, {"name": "Sản phẩm bao gồm", "value": "Áo bơi chống nắng ngắn tay nam Aqua Marina MIRAI MEN''S RASHGUARD C-M18SS-NA-8373"}]'::jsonb, 13, 0, TRUE, '2026-10-23T17:14:12.214039+07:00', '2026-10-23T17:14:12.214039+07:00'),
	(3, 97, 'Áo bơi chống nắng nam Scene Men''s Rashguard SS C-M17SS-WH', 'ao-boi-chong-nang-nam-scene-men-s-rashguard-ss-c-m17ss-wh-7684', 'Áo bơi chống nắng nam Scene Men''s Rashguard SS C-M17SS-WH - 7684 là chiếc áo cho phép người dùng hoạt động thoải mái, hiệu quả, bảo vệ tuyệt đối khỏi mặt trời.', '<div> <div><strong>Áo bơi chống nắng nam Scene Men&#39;s Rashguard SS C-M17SS-WH - 7684</strong> là chiếc áo cho phép người dùng hoạt động thoải mái, hiệu quả, cung cấp sự bảo vệ tuyệt đối khỏi mặt trời và mẩn đỏ, giúp tăng sức hấp dẫn và phong cách cho người mặc. Cấu trúc và thiết kế thông minh với thiết kế đai hông siêu co giãn tăng cường mức độ thoải mái và tinh hoạt một cách toàn diện. </div> <ul><li>Áo bơi chống nắng chất lượng cao mang lại sự linh hoạt tối đa cho người dùng</li><li>Chất liệu lycra kháng khuẩn ngăn chặn vi khuẩn sinh sôi</li><li>Đường may phẳng linh hoạt, nhẹ nhàng với da, không gây khó chịu với da</li><li>Chất liệu nylon co giãn và ống tay raglan mang lại sự tự nhiên khi cử động</li><li>Chống tia UV (UPF 50&#43;)</li></ul> <p><strong>HƯỚNG DẪN CHỌN SIZE ĐỒ BƠI NAM: </strong></p> <ul><li>Size S: 48~53 kg</li><li>Size M: 54~60 kg</li><li>Size L: 61~66 kg</li><li>Size XL: 67~72 kg</li></ul> <div><strong>Aqua Marina</strong> là một thương hiệu chuyên sản xuất các loại thuyền thể thao, thuyền bơm hơi, ván chèo đứng SUP, phụ kiện thuyền như bơm, mái chèo, túi khô. Được thành lập vào năm 2002, Aqua Marina đã chiếm thị phần lớn trong thị trường thuyền và ván chèo đứng bơm hơi toàn cầu bằng việc cung cấp các sản phẩm đa dạng, chất lượng cao, với giá cả phải chăng.</div> <div><img alt="thuong-hieu-aqua-marina-sup-2017-campvivo_vn" height="212" loading="lazy" src="https://wetrek.vn/pic/products/images/636150854008050526.jpg.ashx" width="630" /></div> <div>Áo bơi chống nắng rashguard được thiết kế để bảo vệ người mặc khỏi những vết mẩn đỏ, trầy xước do bị chà xát, hoặc bị cháy nắng do da tiếp xúc với ánh nắng mặt trời trong thời gian dài. Người dùng có thể chỉ mặc riêng loại áo này hoặc mặc kết hợp bên trong bộ đồ bơi giữ nhiệt wetsuit, phù hợp cho các hoạt động như lướt sóng, chèo thuyền - kayak, chèo SUP, lướt ván buồn, lặn hay bơi lội.  Tất cả áo bơi chống nắng Aqua Marina đều làm từ chất liệu len jecxi spandex chống tia UV, độ đàn hồi cao. Độ bền và cảm giác sờ ở tay của loại vải cao cấp này là vô cùng ấn tượng. Áo bơi chống nắng Aqua Marina mang thoải mái, vừa vặn, bảo vệ người dùng khỏi bức xạ tia UV, các vết mẩn đỏ hay bị lạnh.   <div><img alt="ao-boi-chong-nang-nam-scene-mens-rashguard-ss-c-m17ss-wh-7684-campvivo_vn-1" height="427" src="https://wetrek.vn/pic/Product/ctv1.Campvivo&#64;gmail.com/images/ao-boi-chong-nang-nam-scene-mens-rashguard-ss-c-m17ss-wh-7684-Campvivo_vn-1.jpg" width="730" /></div> </div> <p>Xem thêm các sản phẩm <a href="/categories/ao-boi" rel="nofollow"><strong>Áo bơi</strong></a> tại <strong><a href="/" rel="nofollow">Campvivo.VN</a></strong></p> </div>', 'AQUA MARINA', 825000, '[{"name": "Xuất xứ", "value": "Chính hãng"}, {"name": "Chất liệu", "value": "87% nylon , 13% spandex + lycra"}, {"name": "Hướng dẫn sử dụng", "value": "Giặt máy với nước lạnh"}, {"name": "Sản phẩm bao gồm", "value": "1x Áo bơi chống nắng nam Scene Men''s Rashguard SS C-M17SS-WH - 7684"}]'::jsonb, 25, 0, TRUE, '2026-10-23T17:14:12.238895+07:00', '2026-10-23T17:14:12.238895+07:00'),
	(4, 178, 'Ấm nước dã ngoại 2.8L Petromax Perkomax LE28', 'am-nuoc-da-ngoai-2-8l-petromax-perkomax-le28', 'Ấm nước chuyên dụng pha cafe, là dụng cụ không thể thiếu với những người thích cafe cùng trải nghiệm dã ngoại độc đáo.', '<p>Ấm nước dã ngoại chuyên dụng để pha cafe, mang tới trải nghiệm độc đáo cùng sự tiện dụng trong những chuyến dã ngoại cùng với bạn bè và gia đình.</p> <p><img alt="Ấm nước dã ngoại 2.8L Petromax Perkomax LE28" height="997" loading="lazy" src="https://wetrek.vn/pic/products/images/LE28-mitEinzelteilen.jpg" width="1000" /></p> <p><strong>Đặc điểm nổi bật:</strong></p> <ul><li>Núm cầm bằng thủy tinh chống nóng.</li><li>Chất liệu thép không gỉ chắc chắn.</li><li>Ấm đi kèm bộ phụ kiện pha cà phê tiện lợi khi sử dụng.</li></ul> <p><img alt="" height="667" loading="lazy" src="https://wetrek.vn/pic/products/images/le28-Detail_Oese.jpg" width="1000" /></p> <p><strong>Thông số sản phẩm:</strong></p> <strong>Thương hiệu</strong>Petromax<strong>Xuất xứ</strong>Đức<strong>Kích thước</strong>20x20x22 cm (DxRxC)<strong>Dung tích</strong>2.8L<strong>Trọng lượng</strong>1,25kg <p><img alt="" height="1000" loading="lazy" src="https://wetrek.vn/pic/products/images/LE_Glasknopf-einzeln.jpg" width="1000" /></p>', 'PETROMAX', 3900000, '[]'::jsonb, 55, 0, TRUE, '2026-10-23T17:14:12.45724+07:00', '2026-10-23T17:14:12.45724+07:00'),
	(5, 178, 'Ấm đun nước Titanium Naturehike Titanium Kettle NH21CJ007', 'am-dun-nuoc-titanium-naturehike-titanium-kettle-nh21cj007', 'Ấm đun nước titan Naturehike NH21CJ007 chỉ 185g, chống gỉ, chịu nhiệt cao, dung tích 0.8-1L. Bạn đồng hành lý tưởng khi trekking. Mua ngay tại Campvivo!', '<div><p>Với những ai mê đi bộ đường dài và đếm từng gram hành lý, một chiếc ấm vừa nhẹ vừa bền là báu vật. <strong>Ấm đun nước Titanium Naturehike NH21CJ007</strong> đáp ứng trọn vẹn điều đó: thân ấm titan nguyên khối chỉ nặng 185g nhưng chịu được nhiệt độ cao, chống gỉ sét và bền bỉ qua nhiều mùa cắm trại.</p> <p><img loading="lazy" src="https://wetrek.vn/pic/products/images/639177479141753290.jpg.ashx" alt="Ấm đun nước titan Naturehike NH21CJ007 siêu nhẹ cho trekking" /></p> <h2>Vì sao chọn chất liệu titan?</h2> <p>Hợp kim titan không chỉ nhẹ mà còn trơ với axit và kiềm, không dễ rỉ sét hay biến chất khi tiếp xúc lửa và nước nhiều lần. Bề mặt ấm xuất hiện kết cấu vỏ cam đặc trưng, đó chính là hoa văn tự nhiên hình thành khi cán tấm titan chất lượng cao, vừa tăng độ thẩm mỹ vừa là dấu hiệu của vật liệu tốt.</p> <ul><li>Chất liệu hợp kim titan: chống gỉ, chịu axit kiềm, chịu nhiệt độ cao</li><li>Vòi rót thiết kế mịn, rót nước gọn không nhỏ giọt</li><li>Hoa văn vòng chống trượt ở đáy giúp ấm đứng vững trên bếp</li><li>Các khớp kết nối khít, chắc chắn khi đun nấu</li></ul> <p><img loading="lazy" src="https://wetrek.vn/pic/products/images/639177479143315873.jpg.ashx" alt="Chi tiết vòi rót và đáy chống trượt của ấm titan Naturehike NH21CJ007" /></p> <h2>Thông số kỹ thuật</h2> <ul><li>Thương hiệu: Naturehike - Dòng Glamping</li><li>Mã sản phẩm: NH21CJ007</li><li>Chất liệu: Titanium</li><li>Kích thước sử dụng: 167 x 149 x 150 mm</li><li>Kích thước đóng gói: 170 x 170 x 170 mm</li><li>Trọng lượng: 185g (kèm túi đựng 70g)</li><li>Dung tích: 0.8L hoặc 1L</li><li>Màu: Titanium - Xuất xứ: Trung Quốc</li></ul> <h3>Dùng được cả trong nhà lẫn ngoài trời</h3> <p>Không chỉ giới hạn ở những chuyến trekking, cắm trại hay dã ngoại, NH21CJ007 còn là chiếc ấm đẹp mắt để dùng tại nhà. Hai dung tích 0.8L và 1L cho bạn lựa chọn phù hợp với số người trong đoàn. Lưu ý nhỏ: tránh dùng vật cứng như bi thép để cọ rửa nhằm giữ bề mặt ấm luôn sáng đẹp.</p> <p>Đặt mua <strong>Ấm đun nước Titanium Naturehike NH21CJ007</strong> chính hãng tại Campvivo để hành trang thêm nhẹ mà vẫn đủ tiện nghi.</p></div>', 'NATUREHIKE', 1605000, '[]'::jsonb, 0, 0, TRUE, '2026-10-23T17:14:12.470135+07:00', '2026-10-23T17:14:12.470135+07:00'),
	(6, 174, 'Ấm đun nước 1L Campingmoon S1000', 'am-dun-nuoc-1l-campingmoon-s1000', 'Ấm đun nước với trọng lượng siêu nhẹ cùng chất liệu nhôm nguyên khối chắc chắn và khả năng truyền nhiệt nhanh, thuận tiện đun nấu trong những chuyến dã ngoại.', '<p>Ấm đun nước với trọng lượng siêu nhẹ cùng chất liệu nhôm nguyên khối chắc chắn và khả năng truyền nhiệt nhanh, thuận tiện đun nấu trong những chuyến dã ngoại.</p> <p><strong>Đặc điểm nổi bật:</strong></p> <ul><li>Mặt đáy to tối ưu nhiệt khi sử dụng bếp dã ngoại hay hố lửa.</li><li>Tay cầm tránh bỏng cho người sử dụng</li><li>Miệng bình ngắn và cao giúp tối ưu thể tích mà vẫn đảm bảo thuận tiện khi sử dụng</li><li>Chất liệu nhôm nguyên khối đảm  bảo độ bền và tối ưu trọng lượng sản phẩm</li></ul> <p><img alt="Ấm đun nước 1L Campingmoon S1000" height="589" loading="lazy" src="https://wetrek.vn/pic/products/images/am-dun-nuoc-1l-10139%20%281%29.jpg" width="1000" /></p>', 'CAMPINGMOON', 349000, '[{"name": "Xuất xứ", "value": "Trung Quốc"}, {"name": "Trọng lượng", "value": "280g"}, {"name": "Chất liệu", "value": "Nhôm nguyên khối"}]'::jsonb, 31, 0, TRUE, '2026-10-23T17:14:12.548077+07:00', '2026-10-23T17:14:12.548077+07:00'),
	(7, 174, 'Bộ nồi dã ngoại 2-3 người Naturehike Tableware Camping Set 4in1 Picnic NH15T203-G - 9671', 'bo-noi-da-ngoai-2-3-nguoi-naturehike-tableware-camping-set-4in1-picnic-nh15t203-g-9671', 'Thiết kế xếp chồng gọn gàng, tiết kiệm diện tích nên có thể dễ dàng mang theo trong các chuyến leo núi, cắm trại, picnic, thám hiểm, sinh tồn…', '<p><strong>Bộ nồi dã ngoại 2-3 người Naturehike Tableware Camping Set 4in1 Picnic NH15T203-G - 9671</strong> có thiết kế xếp chồng gọn gàng, tiết kiệm diện tích nên có thể dễ dàng mang theo trong các chuyến leo núi, cắm trại, picnic, thám hiểm, sinh tồn&#x2026;</p> <p><img alt="Bộ nồi dã ngoại 2-3 người Naturehike Tableware Camping Set 4in1 Picnic NH15T203-G - 9671" height="504" src="https://wetrek.vn/pic/Product/2h&#64;Campvivo.vn/images/B%E1%BB%99%20n%E1%BB%93i%20d%C3%A3%20ngo%E1%BA%A1i%202-3%20ng%C6%B0%E1%BB%9Di%20Naturehike%20Tableware%20Camping%20Set%204in1%20Picnic%20NH15T203-G%20-%209671%20%284%29.jpg" width="800" /></p> <p><strong>Bộ nồi dã ngoại 2-3 người Naturehike Tableware Camping Set 4in1 Picnic NH15T203-G - 9671</strong> có thể dùng để nấu nướng thức ăn đủ cho 1-3 người.</p> <p>Một số ưu điểm nổi bật của sản phẩm:</p> <ul><li>Bộ nồi gồm 3 sản phẩm có thể xếp gọn, tiết kiệm diện tích khi di chuyển và dễ dàng mang theo người, bao gồm: 1 chảo, 1 nồi nhỏ, 1 nồi lớn. Kích thước của từng thành phần:</li></ul> <ol><li>Nồi nhỏ: 14,8 x 8x5 cm</li><li>Nồi lớn: 17,2 x 9,8 cm</li><li>Chảo: 18 x 4,3 cm</li></ol> <ul><li>Kích thước tổng của bộ nồi là 19 x 10 x 18 cm và trọng lượng tổng là 680 g.</li><li>Bộ sản phẩm sử dụng chất liệu hợp kim Nhôm giúp hấp thụ nhiệt tốt, giúp thức ăn nhanh chín hơn. Bạn có thể chế biến các món ăn phổ thông: xào, luộc, rán, hấp.. một cách nhanh chóng.</li><li>Trong lòng nồi, chảo còn được phủ một lớp chống dính ngăn bám thức ăn, không mất nhiều thời gian vệ sinh sau khi sử dụng.</li><li>Phần tay cầm và quai nồi được thiết kế có thể đóng mở, khi không cần sử dụng sẽ ôm sát vào thân nhằm hạn chế vướng víu.</li><li>Tay cầm đều được phủ lớp nhựa tổng hợp chịu nhiệt, rất bền bỉ. Nó cũng có tác dụng chống nóng, không làm bỏng tay người dùng.</li><li>Với mỗi sản phẩm, đều có nắp vung đậy sẵn nhằm hạn chế khói, bụi bẩn làm ảnh hưởng tới thức ăn trong quá trình nấu nướng.</li><li><strong>Naturehike</strong> đã trang bị thêm cho người dùng một bộ 3 dụng cụ vệ sinh, làm sạch cùng một cốc đo lượng nước.</li></ul> <p><strong>Giới thiệu về thương hiệu Naturehike:</strong></p> <p>Được thành lập vào năm 2005, <strong>Naturehike</strong> là một thương hiệu sản phẩm ngoài trời chuyên nghiệp. Ủng hộ khái niệm thương hiệu về “du lịch ngoài trời nhẹ nhàng” và cam kết cung cấp các thiết bị ngoài trời có trọng lượng nhẹ chất lượng cao. Họ là một doanh nghiệp thương hiệu chuyên về nghiên cứu và phát triển sản phẩm, thiết kế và sản xuất. <strong>Naturehike</strong> bán những sản phẩm phục vụ đi bộ đường dài, leo núi, cắm trại và các sản phẩm thể thao ngoài trời khác.</p> <p>Thương hiệu <strong>Naturehike</strong> tạo ra các thiết bị ngoài trời tự nhiên, nhẹ và chuyên nghiệp. Sản phẩm của họ trải qua quá trình sản xuất và thử nghiệm tinh vi. Tất cả các sản phẩm của <strong>Naturehike</strong> đều được kiểm tra và thử nghiệm bởi chuyên viên có kinh nghiệm ngoài trời, những người tham gia vào khâu sản xuất từ đầu đến cuối. <strong>Naturehike</strong> tự hào với chất lượng sản phẩm của họ và đảm bảo rằng chất liệu và tay nghề sẽ không có sai sót.</p> <p><strong>Naturehike</strong> thiết kế những sản phẩm khiến việc ra ngoài trời thoải mái hơn và ít phức tạp hơn. Thương hiệu này cũng rất coi trọng trải nghiệm và phản hồi của khách hàng để đảm bảo sự phát triển và cải tiến hơn nữa cho sản phẩm của mình. Điều này đã làm cho <strong>Naturehike</strong> trở thành một thương hiệu chất lượng, có tiếng tăm trong cộng đồng thể thao ngoài trời.</p> <p>Chúng ta có thể thấy, <strong>Naturehike</strong> sử dụng vẻ đẹp của thiên nhiên làm nguồn cảm hứng để nâng cao trải nghiệm hàng ngày cho người dùng ủng hộ việc đi bộ đường dài tự nhiên và phóng khoáng.</p>', 'NATUREHIKE', 550000, '[{"name": "Xuất xứ", "value": "Trung Quốc"}, {"name": "Màu sắc", "value": "Ghi xám"}, {"name": "Kích thước", "value": "19 x 10 x 18 cm"}, {"name": "Trọng lượng", "value": "680 g"}, {"name": "Chất liệu", "value": "Hợp kim nhôm"}, {"name": "Sản phẩm bao gồm", "value": "Bộ nồi dã ngoại 2-3 người Naturehike Tableware Camping Set 4in1 Picnic NH15T203-G - 9671"}]'::jsonb, 15, 0, TRUE, '2026-10-23T17:14:12.79362+07:00', '2026-10-23T17:14:12.79362+07:00'),
	(8, 256, 'Áo đi mưa Coleman PVC 2000014625 - S/ M - Tím', 'ao-di-mua-coleman-pvc-2000014625-s-m-tim', 'Áo đi mưa Coleman PVC 2000014625 - S/ M – Tím có thiết kế trùm đầu với dây kéo và nút bấm, cổ tay áo có thể điều chỉnh được, chất liệu siêu nhẹ, chống thấm nước.', '<div> <div><strong>Coleman</strong> là hãng sản xuất đồ outdoor nổi tiếng thế giới, bắt đầu các sản phẩm đèn chiếu sáng. Theo thời gian, Coleman dần dần có chỗ đứng vững chắc trên thị trường với nhiều sản phẩm phục vụ <strong>du lịch - dã ngoại</strong> và các hoạt động ngoài trời. Các sản phẩm của Coleman rất đa dạng, từ đèn chiếu sáng, thùng đá giữ nhiệt, đệm hơi, balo, phụ kiện cho tới những dụng cụ sinh tồn, dụng cụ nhà bếp cần thiết. Ngày này, các sản phẩm Coleman được phân phối rộng rãi khắp các châu lục, tại nhiều quốc gia trên thế giới.<br />  </div> <div></div> <div> <br /> <strong>Áo đi mưa Coleman PVC 2000014625 - S/ M – Tím </strong>có thiết kế trùm đầu với dây kéo và nút bấm, cổ tay áo có thể điều chỉnh được. Chất liệu siêu nhẹ, chống thấm nước, giúp bạn thoải mái di chuyển dưới trời mưa.<br />  </div> <div><img alt="Ao-di-mua-COLEMAN-PVC-2-Campvivo_VN" height="354" src="https://wetrek.vn/pic/Product/hoanghien150993&#64;gmail.com/images/Ao-di-mua-COLEMAN-PVC-2-Campvivo_VN.jpg" width="630" /></div> <div> <br /> Xem thêm các sản phẩm <strong>Đồ chống nước Coleman </strong>tại<strong> Campvivo.VN</strong></div> </div>', 'COLEMAN', 399000, '[{"name": "Màu sắc", "value": "Tím"}, {"name": "Chất liệu", "value": "PVC"}, {"name": "Kích cỡ", "value": "S/M"}, {"name": "Sản phẩm bao gồm", "value": "Áo đi mưa Coleman PVC 2000014625 - S/ M - Tím"}]'::jsonb, 40, 0, TRUE, '2026-10-23T17:14:13.82572+07:00', '2026-10-23T17:14:13.82572+07:00'),
	(9, 136, 'Áo dài tay Gothiar Comfort Sweatshirt Red Logo', 'ao-dai-tay-gothiar-comfort-sweatshirt-red-logo', 'Áo dài tay Gothiar Comfort Sweatshirt Red Logo - Với thiết kế đơn giản, form dáng vừa vặn, chất liệu vải dày dặn, ấm áp, giúp mang lại sự năng động, trẻ trung, ấm áp cho người mặc, Logo Gothiar nổi bật, cá tính.', '<p>Áo dài tay Gothiar Comfort Sweatshirt là một trong những sản phẩm mới nhất của thương hiệu thời trang Gothiar. Với thiết kế đơn giản, form dáng vừa vặn, chất liệu vải <strong>Polyester</strong> dày dặn, ấm áp, áo là sự lựa chọn hoàn hảo cho mọi người yêu thích phong cách trẻ trung, năng động.</p> <p><img alt="Áo dài tay Gothiar Comfort Sweatshirt Red Logo" height="960" loading="lazy" src="https://wetrek.vn/pic/general/images/photo_18_2025-02-28_09-10-04.jpg" width="960" /></p> <p> </p> <p><strong>Form dáng regular vừa vặn, thoải mái vận động</strong></p> <p>Áo dài tay Gothiar Comfort Sweatshirt có form dáng regular, vừa vặn với người mặc, không quá ôm cùng không quá rộng. Thiết kế này giúp đảm bảo sự thoải mái cho người mặc khi vận động, di chuyển.</p> <p><strong>Chất liệu vải dày dặn, ấm áp</strong></p> <p>Áo được làm từ chất liệu vải <strong>Polyester</strong> dày dặn, có khả năng giữ ấm tốt. Chất vải mềm mại, mang lại cảm giác thoải mái, dễ chịu cho người mặc.</p> <p><strong>Thiết kế áo tay dài ấm áp</strong></p> <p>Thiết kế áo tay dài giúp giữ ấm cơ thể hiệu quả, phù hợp với thời tiết se lạnh. Áo có cổ tròn,  giúp tạo phong cách ấn tượng cho người mặc.</p> <h4><strong>Logo Gothiar Ấn Tượng:</strong></h4> <ul><li>Ngực áo được in thêm logo <strong>Gothiar </strong>nổi bật, tạo nên điểm nhấn đặc biệt và là dấu ấn riêng biệt cho người mặc.</li></ul> <p><img alt="Áo dài tay Gothiar Comfort Sweatshirt Red Logo" height="1000" loading="lazy" src="https://wetrek.vn/pic/products/images/638772173961300237.jpg.ashx" width="1000" /></p> <p> </p> <p><strong>Màu sắc đa dạng</strong></p> <p>Áo dài tay Gothiar Comfort Sweatshirt có nhiều màu sắc đa dạng, phù hợp với mọi phong cách thời trang. Khách hàng có thể thoải mái lựa chọn màu phù hợp với sở thích và cá tính của mình.</p> <p><strong>Phối đồ đa dạng</strong></p> <p>Áo dài tay Gothiar Comfort Sweatshirt mang phong cách đơn giản nên có thể dễ dàng phối đồ cùng nhiều loại quần áo khác nhau. Các chàng trai có thể kết hợp áo với quần jean, quần short, quần kaki,... để tạo nên những set đồ năng động, trẻ trung. Áo cũng có thể được mặc để đi chơi, đi làm, đi học,...</p> <p>Mua ngay các sản phẩm <a href="/categories/ao-ni-hoodie" rel="nofollow"><strong>Áo dài tay</strong></a> tại <strong><a href="/" rel="nofollow">campvivo.vn</a></strong></p>', 'GOTHIAR', 439000, '[{"name": "Xuất xứ", "value": "Chính hãng"}, {"name": "Chất liệu", "value": "95% Polyester và 5% Spandex"}, {"name": "Màu sắc", "value": "Đen, nâu, xanh lá, trắng, vàng"}]'::jsonb, 29, 0, TRUE, '2026-10-23T17:14:16.174928+07:00', '2026-10-23T17:14:16.174928+07:00'),
	(10, 244, 'Áo khoác gió 2 lớp nam Gothiar Popular', 'ao-khoac-gio-2-lop-gothiar-2l-jacket-do-8974', 'Áo khoác gió 2 lớp nam Gothiar Popular với thiết kế 2 lớp với mặt ngoài được dệt từ vải Gore-Tex, mặt trong được tráng lớp PU giúp cho việc chống thấm được tốt và giữ ấm cho cơ thể. Trọng lượng nhẹ có thể gấp gọn một cách tiện lợi.', '<div> <p>Đi bộ đường dài, leo núi, cắm trại trong môi trường tự nhiên và các khu vực miền núi chắc chắn sẽ thú vị hơn với trang phục ngoài trời phù hợp. Điểm nhấn đặc biệt để lựa chọn trang phục khi đi dã ngoại là phải đáp ứng được các điều kiện về chống thấm, chống gió, hơn nữa các loại vải phải có độ thoáng khí cao và nhanh khô. Trang phục Gothiar đáp ứng được đầy đủ các yêu cầu, là sự lựa chọn trang hàng đầu khi tham gia các hoạt động dã ngoại, thể thao ngoài trời, trong nhiều điều kiện thời tiết, địa hình và mức độ chuyên nghiệp khác nhau. </p> <p>Với tất cả sự tôn trọng và cùng chung niềm đam mê outdoor, GOTHIAR luôn nổ lực khích lệ mọi người tích cực tham gia các hoạt động diễn ra ngoài trời. Gothiar cam kết phụng sự cuộc sống gần gũi với thiên nhiên của con người Việt Nam và hướng tới mục tiêu phát triển bền vững, bảo vệ những nét đẹp và giá trị của tự nhiên.</p> <p><img alt="Áo khoác gió 2 lớp nam Gothiar Popular" height="1024" loading="lazy" src="https://wetrek.vn/pic/general/images/vn-11134207-7ras8-m3uas3e5hvw56c.jpg" width="1024" /></p> <p>Những đặc điểm của sản phẩm <strong>Áo khoác gió nam Gothiar 2 lớp Popular:</strong></p> <ul><li>Chất liệu: Công nghệ vải GORE-TEX có thể dễ dàng đáp ứng với các thử nghiệm môi trường khác nhau. Lớp ngoài kháng nước, chống xước; Lớp lót vải lưới được tráng lớp PU chống thấm, cản gió tốt mà vẫn đảm bảo thoáng khí. Bạn sẽ ấm hơn khi trời lạnh và khô hơn khi đổ mồ hôi.</li><li>Thiết kế: Áo khoác GOTHIAR áp dụng thiết kế 2 lớp đa chức năng với hệ thống túi có khoá kéo từ ngoài vào trong, khoá kéo thoát khí ở nách, mũ trùm đầu điều chỉnh kép,... Mọi phép đo, form dáng và tính năng đều được cân nhắc kỹ lưỡng để mang lại sự vừa vặn, thoải mái, dễ thở và hiệu suất tối ưu khi vận động, phù hợp để mặc hoặc phối theo lớp.</li><li>Áo có kèm mũ đằng sau cùng khả năng kéo rút tiện lợi, bảo vệ đầu khỏi cái lạnh.Lớp lót bên trong áo 2 lớp Gothiar form âu được làm bằng lưới, vừa giữ ấm vừa giúp cho áo luôn thoáng gió.</li><li>Hệ thống túi khóa hai bên hông, bên trong áo, trước ngực cực kì tiền dụng khi đựng đồ cá nhân.</li><li>Ống tay áo có miếng dán có thể điều chỉnh, bo gọn cổ tay giúp chống gió</li><li>Phong cách Gothiar định hỉnh bởi sự trẻ trung, năng động với màu sắc nổi bật, được lấy cảm hứng từ thiên nhiên.</li></ul> <p>Mua ngay các sản phẩm <strong><a href="/brands/gothiar" rel="nofollow">GOTHIAR</a></strong> tại <strong><a href="/" rel="nofollow">Campvivo</a></strong></p> </div>', 'GOTHIAR', 695000, '[{"name": "Xuất xứ", "value": "Chính hãng"}, {"name": "Chất liệu", "value": "50% NYLON và 50% Polyester"}, {"name": "Công nghệ", "value": "Gore-Tex"}]'::jsonb, 61, 0, TRUE, '2026-10-23T17:14:16.361332+07:00', '2026-10-23T17:14:16.361332+07:00'),
	(11, 136, 'Áo hoodie Gothiar Comfort Warm Up Red Logo', 'ao-hoodie-gothiar-comfort-warm-up-red-logo', 'Áo hoodie là loại áo được thiết kế khá rộng rãi, có mũ, được may bằng chất liệu nỉ, thường có khóa để mặc như một chiếc áo khoác hoặc không khóa như một chiếc áo phông, thường dài đến ngang hông.', '<p>Chắc chắn bạn đã nghe đến áo hoodie - một biểu tượng thời trang đầy thoải mái và phong cách. <strong>Áo hoodie Gothiar Comfort Warm Up Red Logo</strong> không chỉ là một chiếc áo, mà còn là biểu tượng của sự thoải mái và sành điệu.</p> <p><img alt="Áo hoodie Gothiar Comfort Warm Up Red Logo" height="1000" loading="lazy" src="https://wetrek.vn/pic/general/images/z6121713661152_e33393bdef5d30ade08d.jpg" width="1000" /></p> <p> </p> <p>Là mẫu hoodie phổ biến nhất hiện nay với một số đặc trưng như:</p> <h4><strong>Thiết Kế Rộng Rãi và Có Mũ:</strong></h4> <ul><li>Áo được thiết kế khá rộng rãi, tạo cảm giác thoải mái và tự do vận động. Mũ được tích hợp giúp bảo vệ đầu khỏi gió và mưa nhẹ.</li></ul> <h4><strong>Không Khóa và Đai:</strong></h4> <ul><li>Mẫu hoodie phổ biến với thiết kế không khóa, có đai giúp tăng thêm sự tiện ích và tạo điểm nhấn thời trang.</li></ul> <h4><strong>Chiều Dài Đến Thắt Lưng:</strong></h4> <ul><li>Áo có chiều dài vừa đến thắt lưng, tạo nên vẻ ngoại hình trẻ trung và hiện đại.</li></ul> <h4><strong>Phần Túi Lớn Ở Trước Bụng:</strong></h4> <ul><li>Một chi tiết không thể thiếu - phần túi lớn ở trước bụng. Không chỉ là điểm nhấn thời trang mà còn giúp giữ ấm tay hiệu quả.</li></ul> <p><img alt="Áo hoodie Gothiar Comfort Warm Up Red Logo" height="1000" loading="lazy" src="https://wetrek.vn/pic/general/images/e-cc45-48f5-9d85-852de83e9bbd.jpg" width="1000" /></p> <h4><strong>Chất Liệu Mỏng Nhẹ và Thoáng Mát:</strong></h4> <ul><li>Áo được làm từ chất liệu mỏng nhẹ, thoáng mát, ít nhăn, giữ form đứng và đa dạng về màu sắc.</li></ul> <h4><strong>Logo Gothiar Ấn Tượng:</strong></h4> <ul><li>Ngực áo được in thêm logo <strong>Gothiar </strong>nổi bật, tạo nên điểm nhấn đặc biệt và là dấu ấn riêng biệt cho người mặc.</li></ul> <p><img alt="Áo hoodie Gothiar Comfort Warm Up Red Logo" height="1000" loading="lazy" src="https://wetrek.vn/pic/general/images/33-17d2-b3d2-84a7993ced0e.jpg" width="1000" /></p> <p> </p> <p>Với thiết kế đơn giản nhưng không kém phần ấn tượng, chiếc áo này phù hợp cho mọi hoàn cảnh - từ đi học, đi làm đến những buổi dạo phố thoải mái.</p> <p>Việc giặt giũ và phơi áo trở nên dễ dàng và nhanh chóng. Chất liệu chọn lọc giúp áo giữ được hình dáng và màu sắc lâu dài.</p> <p><strong>Áo hoodie Gothiar Comfort Warm Up Red Logo</strong> không chỉ là một chiếc áo, mà là biểu tượng của phong cách và thoải mái. Hãy sở hữu ngay để trải nghiệm sự kết hợp hoàn hảo này!</p> <p>Mua ngay các sản phẩm <strong><a href="/categories/ao-ni-hoodie" rel="nofollow">Áo Hoodie</a></strong> tại <strong><a href="/" rel="nofollow">campvivo.vn</a></strong></p>', 'GOTHIAR', 489000, '[{"name": "Xuất xứ", "value": "Chính hãng"}, {"name": "Chất liệu", "value": "95% Polyester và 5% Spandex"}, {"name": "Màu sắc", "value": "Đen, xanh lá"}]'::jsonb, 87, 0, TRUE, '2026-10-23T17:14:16.571353+07:00', '2026-10-23T17:14:16.571353+07:00'),
	(12, 134, 'Áo khoác gió 2 lớp nam Gothiar Windproof Jacket Nature', 'ao-khoac-gio-2-lop-gothiar-2l-jacket-xanh-la-9313', 'Áo khoác gió 2 lớp nam Gothiar Windproof Jacket Nature có thiết kế 2 lớp với mặt ngoài được dệt từ vải Gore-Tex, mặt trong được tráng lớp PU giúp cho việc chống thấm được tốt và giữ ấm cho cơ thể. Trọng lượng nhẹ có thể gấp gọn một cách tiện lợi.', '<div><img alt="Áo khoác gió 2 lớp Gothiar 2L jacket - Xanh lá 9319" height="381" src="https://wetrek.vn/pic/Product/vuongkientoan.Campvivo&#64;gmail.com/images/GOTHIAR%20LOGO_WHITE.jpg" width="596" /></div> <div> <p><strong>Áo Khoác Gió </strong>là những trang phục không thể thiếu với mỗi người, đặc biệt là những người thường xuyên di chuyển đến những nơi có môi trường thời tiết lạnh giá để tham gia các hoạt động leo núi, dã ngoại. Ngày nay ngoài việc cung cấp sự ấm áp cho cơ thể, <strong>Áo khoác gió</strong> còn rất được yêu chuộng bởi kiểu dáng phong cách của chúng đem lại, thể hiện được sự cá tính của người sử dụng và đặc biệt phù hợp với nhiều tầng lớp lứa tuổi.</p> <p> <strong>Campvivo.VN</strong> xin giới thiệu sản phẩm<strong> </strong>Áo khoác gió 2 lớp Gothiar Windproof Jacket Nature</p> <p><img alt="Áo khoác gió 2 lớp nam Gothiar Windproof Jacket Nature" height="1024" loading="lazy" src="https://wetrek.vn/pic/general/images/vn-11134207-7ras8-m3kgxiqqgc7092.jpg" width="1024" /></p> <div> <p><strong>Những đặc điểm của sản phẩm Áo khoác gió 2 lớp Gothiar Windproof Jacket Nature</strong></p> <p><img alt="Áo khoác gió 2 lớp Gothiar Windproof Jacket Nature" height="1024" loading="lazy" src="https://wetrek.vn/pic/general/images/vn-11134207-7ras8-m3lhubuqmv1x6f.jpg" width="1024" /></p> <p>Áo được thiết kế 2 lớp với chất liệu lớp ngoài được dệt từ vải Gore-Tex, lớp lót được tráng lớp PU chống thấm, giúp cho khả năng chống thấm tốt trong điều kiện mưa nhẹ, cùng khả năng cản gió tốt, đem lại cảm thoải mái khi mặc, phù hợp khi đi ra ngoài với thời tiết lạnh nhiều gió và ẩm ướt.</p> <p>Thiết kế dáng suông và tay thun tạo cảm giác thoải mái khi mặc.</p> <p>Áo có kèm mũ đằng sau cùng khả năng kéo rút tiện lợi, bảo vệ đầu khỏi cái lạnh</p>  Xem thêm các sản phẩm <a href="/categories/ao-khoac-gio" rel="nofollow"><strong>Áo khoác- Gió</strong></a> tại <strong><a href="/" rel="nofollow">Campvivo.VN</a></strong></div> </div>', 'GOTHIAR', 695000, '[{"name": "Xuất xứ", "value": "Chính hãng"}, {"name": "Chất liệu", "value": "50% Nylon và 50% Polyester"}, {"name": "Màu sắc", "value": "Xanh"}, {"name": "Sản phẩm bao gồm", "value": "Áo khoác gió 2 lớp Gothiar Windproof Jacket Nature"}]'::jsonb, 7, 0, TRUE, '2026-10-23T17:14:16.731078+07:00', '2026-10-23T17:14:16.731078+07:00'),
	(13, 134, 'Áo khoác gió 2 lớp nữ Gothiar 2L jacket - Đen 8977', 'ao-khoac-gio-2-lop-gothiar-2l-jacket-den-8977', 'Áo khoác gió 2 lớp Gothiar 2L jacket màu đen cho nữ chất liệu Gore-tex cản gió, chống nước nhẹ và thoáng khí phù hợp cho các hoạt động leo núi, dã ngoại, thể thao ngoài trời với các điều kiện địa hình và thời tiết đa dạng.', '<div><img alt="Áo khoác gió 2 lớp Gothiar 2L jacket - Đen 8977" height="381" src="https://wetrek.vn/pic/Product/vuongkientoan.Campvivo&#64;gmail.com/images/GOTHIAR%20LOGO_WHITE.jpg" width="596" /></div> <div> <p><strong>Áo Khoác Gió </strong>là những trang phục không thể thiếu với mỗi người, đặc biệt là những người thường xuyên di chuyển đến những nơi có môi trường thời tiết lạnh giá để tham gia các hoạt động leo núi, dã ngoại. Ngày nay ngoài việc cung cấp sự ấm áp cho cơ thể, <strong>Áo khoác gió</strong> còn rất được yêu chuộng bởi kiểu dáng phong cách của chúng đem lại, thể hiện được sự cá tính của người sử dụng và đặc biệt phù hợp với nhiều tầng lớp lứa tuổi. </p> <p><strong>Campvivo.VN</strong> xin giới thiệu sản phẩm <strong>Áo khoác gió 2 lớp Gothiar 2L jacket - Đen 8977</strong></p> <p><strong><img alt="" src="https://wetrek.vn/pic/Product/vuongkientoan.Campvivo&#64;gmail.com/images/ao-khoac-gio-2-lop-gothiar-2l-jacket-den-8977-Campvivo-vn1.jpg" /></strong></p> <div>Những đặc điểm của sản phẩm <strong>Áo khoác gió 2 lớp Gothiar 2L jacket - Đen 8977</strong></div> <p>Áo được thiết kế 2 lớp với chất liệu lớp ngoài được dệt từ 100% NYLON, lớp lót được dệt từ 50% NYLON và 50% Polyester, cho khả năng chống thấm tốt trong điều kiện mưa nhẹ, cùng khả năng cản gió tốt, đem lại cảm thoải mái khi mặc, phù hợp khi đi ra ngoài với thời tiết lạnh nhiều gió và ẩm ướt.</p> <p>Thiết kế dáng xuống và tay thun tạo cảm giác thoải mái khi mặc.</p> <p>Áo có kèm mũ đằng sau cùng khả năng kéo rút tiện lợi, bảo vệ đầu khỏi cái lạnh</p> *Lưu ý: <p>Mức nhiệt tối đa khi giặt là 40 độ C</p> <p>Không dùng thuốc tẩy</p> <p>Sấy khô ở nhiệt độ thường, mức nhiệt thấp</p> <p>Có thể là ở nhiệt độ trung bình (có thể sử dụng hơi nước)</p> <p>Giặt khô</p>   Xem thêm các sản phẩm <a href="/categories/ao-khoac-gio" rel="nofollow"><strong>Áo khoác- Gió</strong></a> tại <strong><a href="/" rel="nofollow">Campvivo.VN</a></strong></div>', 'GOTHIAR', 695000, '[{"name": "Xuất xứ", "value": "Chính hãng"}, {"name": "Chất liệu", "value": "50% NYLON và 50% Polyester"}, {"name": "Màu sắc", "value": "Đen"}]'::jsonb, 0, 0, TRUE, '2026-10-23T17:14:17.659039+07:00', '2026-10-23T17:14:17.659039+07:00'),
	(14, 245, 'Áo mưa balo 30 - 50L Raincover - 7692', 'ao-mua-balo-30-50l-raincover-7692', 'Áo mưa balo 30 - 50L Raincover - 7692 được làm từ chất liệu 100% Polyester chống nước rất tốt, bề mặt nhẵn bóng khó bám bẩn và dễ dàng làm sạch. Phù hợp sử dụng cho Balo leo núi có thể tích từ 30-50L. Đây là phụ kiện không thể thiếu cho chiếc balo của bạn.', '<p>Áo mưa balo là phụ kiện không thể thiếu cho chiếc balo của bạn. Nó không chỉ giúp balo không bị ướt vào những ngày mưa mà ngay cả những ngày nắng, không mưa thì áo mưa balo chống lại bụi bẩn, giữ cho balo của bạn luôn an toàn và sạch sẽ. Kích thước nhỏ gọn khi gấp lại, dành một góc nhỏ trong balo để áo mưa balo là nó luôn sẵn sàng bảo vệ balo của bạn bất cứ lúc nào.<br /> <br /> <strong>Campvivo.VN</strong> lựa chọn và giới thiệu bạn sản phẩm <strong>Áo mưa balo 30 - 50L Raincover - 7692<br /> <img alt="Áo mưa balo 30 - 50L Raincover - 7692" src="https://wetrek.vn/pic/Product/vuongkientoan.Campvivo&#64;gmail.com/images/ao-mua-balo-30-50l-raincover-7692-Campvivo-vn-1.jpg" /></strong><br /> Xem thêm các sản phẩm <strong>Phụ Kiện Balo - Túi</strong> tại <strong>Campvivo.VN</strong></p>', 'MADE IN VIETNAM', 80000, '[{"name": "Xuất xứ", "value": "VietNam"}, {"name": "Màu sắc", "value": "Vàng"}, {"name": "Chất liệu", "value": "Polyester"}, {"name": "Trọng lượng", "value": "Áo mưa balo 30 - 50L Raincover - 7692"}, {"name": "Thể tích ba lô phù hợp", "value": "30-50L"}, {"name": "Sản phẩm bao gồm", "value": "Áo mưa balo 50-70L Ryder Rucksack Raincover L F1004 - 6700"}]'::jsonb, 0, 0, TRUE, '2026-10-23T17:14:18.454489+07:00', '2026-10-23T17:14:18.454489+07:00'),
	(15, 244, 'Áo khoác gió 2 lớp nam GOTHIAR', 'ao-khoac-gio-2-lop-gothiar-2l-jacket-xam-den-8423', 'Áo khoác gió 2 lớp nam GOTHIAR với chất liệu lớp ngoài được dệt từ 100% NYLON, lớp lót được dệt từ 50% NYLON và 50% Polyester, cho khả năng chống thấm tốt trong điều kiện mưa nhẹ, cùng khả năng cản gió tốt, đem lại cảm thoải mái khi mặc, phù hợp khi đi ra ngoài với thời tiết lạnh nhiều gió và ẩm ướt.', '<div> <p>Đi bộ đường dài, leo núi, cắm trại trong môi trường tự nhiên và các khu vực miền núi chắc chắn sẽ thú vị hơn với trang phục ngoài trời phù hợp. Điểm nhấn đặc biệt để lựa chọn trang phục khi đi dã ngoại là phải đáp ứng được các điều kiện về chống thấm, chống gió, hơn nữa các loại vải phải có độ thoáng khí cao và nhanh khô. Trang phục Gothiar đáp ứng được đầy đủ các yêu cầu, là sự lựa chọn trang hàng đầu khi tham gia các hoạt động dã ngoại, thể thao ngoài trời, trong nhiều điều kiện thời tiết, địa hình và mức độ chuyên nghiệp khác nhau. </p> <p>Với tất cả sự tôn trọng và cùng chung niềm đam mê outdoor, GOTHIAR luôn nổ lực khích lệ mọi người tích cực tham gia các hoạt động diễn ra ngoài trời. Gothiar cam kết phụng sự cuộc sống gần gũi với thiên nhiên của con người Việt Nam và hướng tới mục tiêu phát triển bền vững, bảo vệ những nét đẹp và giá trị của tự nhiên.</p> <p><img alt="Áo khoác gió 2 lớp nam GOTHIAR " height="1000" loading="lazy" src="https://wetrek.vn/pic/general/images/49f7aefa8375485e9f4f4d8d8ff5e388.jpg" width="1000" /></p> <p> Những đặc điểm của sản phẩm <strong>Áo khoác gió GOTHIAR 2 lớp</strong><strong>:</strong></p> <ul><li>Chất liệu: Công nghệ vải GORE-TEX có thể dễ dàng đáp ứng với các thử nghiệm môi trường khác nhau. Lớp ngoài kháng nước, chống xước; Lớp lót vải lưới được tráng lớp PU chống thấm, cản gió tốt mà vẫn đảm bảo thoáng khí. Bạn sẽ ấm hơn khi trời lạnh và khô hơn khi đổ mồ hôi.</li><li>Thiết kế: Áo khoác GOTHIAR áp dụng thiết kế 2 lớp đa chức năng với hệ thống túi có khoá kéo từ ngoài vào trong, khoá kéo thoát khí ở nách, mũ trùm đầu điều chỉnh kép,... Mọi phép đo, form dáng và tính năng đều được cân nhắc kỹ lưỡng để mang lại sự vừa vặn, thoải mái, dễ thở và hiệu suất tối ưu khi vận động, phù hợp để mặc hoặc phối theo lớp.</li><li>Áo có kèm mũ đằng sau cùng khả năng kéo rút tiện lợi, bảo vệ đầu khỏi cái lạnh.Lớp lót bên trong áo 2 lớp Gothiar form âu được làm bằng lưới, vừa giữ ấm vừa giúp cho áo luôn thoáng gió.</li><li>Hệ thống túi khóa hai bên hông, bên trong áo, trước ngực cực kì tiền dụng khi đựng đồ cá nhân.</li><li>Ống tay áo có miếng dán có thể điều chỉnh, bo gọn cổ tay giúp chống gió</li><li>Phong cách Gothiar định hỉnh bởi sự trẻ trung, năng động với màu sắc nổi bật, được lấy cảm hứng từ thiên nhiên.</li></ul> <p><strong><img alt="" height="600" loading="lazy" src="https://wetrek.vn/pic/products/images/638073175183653366.jpg.ashx" width="900" /></strong></p> </div>', 'GOTHIAR', 585000, '[{"name": "Xuất xứ", "value": "Chính hãng"}, {"name": "Chất liệu", "value": "50% NYLON và 50% Polyester"}]'::jsonb, 21, 0, TRUE, '2026-10-23T17:14:18.66239+07:00', '2026-10-23T17:14:18.66239+07:00'),
	(16, 133, 'Áo Cờ Đỏ Sao Vàng Việt Nam', 'ao-co-do-sao-vang-viet-nam', 'Áo Cờ Đỏ Sao Vàng rẻ nhất Việt Nam tại Campvivo.VN. Nhận sản xuất đồng phục áo cờ, in số lượng lớn. Hotline 1900 0000.', '<p><strong>Campvivo.VN - Áo Cờ Đỏ Sao Vàng Việt Nam: </strong>Mỗi khi khoác lên mình chiếc Áo Cờ Đỏ Sao Vàng Tổ Quốc, ai cũng cảm nhận được tình yêu và lòng tự hào dân tộc bởi chiếc Ao Cờ Đỏ Sao Vàng Việt Nam luôn chứa đựng rất nhiều ý nghĩa và thông điệp thiêng liêng.Vì vậy, ngày nay Áo Cờ Đỏ Sao Vàng Việt Nam trở thành một trang phục không thế thiếu trong các hoạt động xã hội, trong các dịp lễ lớn và đặc biệt luôn song hành cùng các bạn trẻ cá tính trên khắp các nẻo đường, xuất hiện trong tất cả các chuyến du lịch dã ngoại, phượt xe máy, phượt ô tô. </p> <div><img alt="ao-co-do-sao-vang-cung-campvivo-vang-tieng-quoc-ca-tren-dinh-fansipan" height="420" loading="lazy" src="https://wetrek.vn/pic/products/images/FANSIPAN%2015_020913.jpg" width="630" /></div> <p>Đáp ứng nhu cầu của đông đảo mọi người và cũng thể hiện niềm tự hào dân tộc, Campvivo tự hào phát động chiến dịch cung cấp áo cờ rẻ nhất trên thị trường.<strong>Campvivo.VN</strong> cam kết bán hàng áo cờ giá gốc không lợi nhuận đến tận tay người tiêu dùng </p> <p><img alt="" height="574" loading="lazy" src="https://wetrek.vn/pic/products/images/bang-size-ao-co-nguoi-lon-Campvivo_vn%281%29.jpg" width="1000" /><img alt="" height="574" loading="lazy" src="https://wetrek.vn/pic/products/images/bang-size-ao-co-tre-em-Campvivo_vn%281%29.jpg" width="1000" /></p> <p></p> <p>Vậy còn chờ gì nữa, mau qua ngay online tại <strong><a href="/" rel="nofollow">Campvivo.VN</a></strong> hay qua trực tiếp <strong><a href="/pages/he-thong-cua-hang" rel="nofollow">Hệ thống Campvivo Store</a></strong> để chọn cho mình một chiếc áo cờ phù hợp nhất nhé.</p>', 'Khác', 33000, '[]'::jsonb, 248, 0, TRUE, '2026-10-23T17:14:19.044014+07:00', '2026-10-23T17:14:19.044014+07:00'),
	(17, 34, 'Áo phao Sterns 3000002204', 'ao-phao-coleman-3000002204', 'Áo phao Sterns 3000002204 được thiết kế tiện lợi, tạo cảm giác thoái mái khi vận động vận động, Lớp ngoài bao phủ bằng chất liệu nylon mềm nhẹ, chống thấm.', '<div><strong>Coleman</strong> là hãng sản xuất đồ outdoor nổi tiếng thế giới, bắt đầu các sản phẩm đèn chiếu sáng. Theo thời gian, Coleman dần dần có chỗ đứng vững chắc trên thị trường với nhiều sản phẩm phục vụ <strong>du lịch - dã ngoại</strong> và các hoạt động ngoài trời. Các sản phẩm của Coleman rất đa dạng, từ đèn chiếu sáng, thùng đá giữ nhiệt, đệm hơi, balo, phụ kiện cho tới những dụng cụ sinh tồn, dụng cụ nhà bếp cần thiết. Ngày này, các sản phẩm Coleman được phân phối rộng rãi khắp các châu lục, tại nhiều quốc gia trên thế giới. <br />  </div> <div></div> <div> <div><br /> <strong>Áo phao Sterns 3000002204 </strong>được thiết kế tiện lợi, tạo cảm giác thoái mái khi vận động vận động, Lớp ngoài bao phủ bằng chất liệu nylon mềm nhẹ, chống thấm.</div> <div><img alt="ao-phao-coleman-3000002204-Campvivo.VN" height="551" src="https://wetrek.vn/pic/Product/chuotnho0o0hht&#64;gmail.com/images/ao-phao-coleman-3000002204-Campvivo_VN.jpg" width="630" /></div>  <br />  <br /> Xem thêm các sản phẩm <a href="/categories/ao-boi" rel="nofollow"><strong>Áo bơi</strong></a> tại <strong><a href="/categories/tui-giu-lanh-tui-giu-nhiet" rel="nofollow">Campvivo.VN</a></strong></div>', 'COLEMAN', 1799000, '[{"name": "Xuất xứ", "value": "Hoa Kỳ"}, {"name": "Màu sắc", "value": "Ghi xám"}, {"name": "Kích thước", "value": "tương đương vòng ngực từ 81 đến >120 cm"}, {"name": "Chất liệu", "value": "nylon"}, {"name": "Sản phẩm bao gồm", "value": "Áo phao coleman 3000002204"}]'::jsonb, 38, 0, TRUE, '2026-10-23T17:14:19.912952+07:00', '2026-10-23T17:14:19.912952+07:00'),
	(18, 137, 'Áo phông nam VNXK MHW Way2Cool™', 'ao-phong-nam-mountain-hardwear', 'Áo phông nam Mountain HardWear Way2Cool™ dệt từ chất liệu có tính co giãn đàn hồi tốt, trọng lượng nhe, mau khô, bền màu và dễ vệ sinh, bảo quản. Sử dụng trong những chuyến picnic, dã ngoại, thể thao ngoài trời.', '<h4><strong>Campvivo - Áo phông nam Mountain Hardwear</strong><br /> Thương hiệu Mountain Hard được thành lập năm 1993 và dần phát triển thành một thương hiệu nổi tiếng thế giới về <a href="/" rel="nofollow">đồ outdoor</a>, nổi bật là quần áo, phụ kiện, túi ngủ,...</h4> <h4><img alt="Áo phông nam VNXK MHW Way2Cool™" height="287" loading="lazy" src="https://wetrek.vn/pic/products/images/logo-Mountain-hardwear.jpg" width="500" /></h4> <h4><a href="/products/ao-phong-nam-mountain-hardwear" rel="nofollow">Áo phông nam Mountain Hardwear</a> là sản phẩm thời trang được thiết kế theo tiêu chí hàng đầu của hãng Mountain Hardwear là phù hợp với các hoạt động ngoài trời, bền và đẹp.</h4> <h4><img alt="" height="500" loading="lazy" src="https://wetrek.vn/pic/products/images/ao-phong-mountain-hardwear02.jpg" width="500" /></h4> <h4>- <strong>Chất liệu</strong>: <a href="/products/ao-phong-nam-mountain-hardwear" rel="nofollow">Áo phông nam Mountain Hardwear</a> được dệt từ sợi polyester và sợi Spandex với đặc tính co giãn tốt, dẻo dai, bền sơi, trọng lượng nhe, mau khô, bền màu và dễ vệ sinh, bảo quản. </h4> <h4><br /> - <strong>Thiết kế</strong>: Dựa trên những thông tin phản hồi từ các vận động viên đẳng cấp thế giới Mountain Hardwear đã ứng dụng công nghệ  Cool.Q ™ ZERO vào sản xuất <a href="/products/ao-phong-nam-mountain-hardwear" rel="nofollow">Áo phông nam Mountain Harwwear </a>- công nghệ hoạt động làm mát đầu tiên của ngành công nghiệp thiết kế, nó giúp giảm nhiệt độ tổng thể của vải khi bạn đổ mồ hôi.</h4> <h4><br /> -<strong> Hoàn cảnh sử dụng</strong>: Với thiết kế cổ điển, màu sắc trang nhã, bạn có thể dễ dàng phối hợp chiếc áo này với nhiều trang phục khác nhau trong đời sống hàng ngày hay những hoạt động thể thao, du lịch, dã ngoại, phượt. </h4> <div><img alt="" height="500" loading="lazy" src="https://wetrek.vn/pic/products/images/ao-phong-mountain-hardwear.jpg" width="500" /></div> <p>Xem thêm chi tiết sản phẩm tại <a href="/products/do-nam" rel="nofollow">ĐỒ NAM.</a></p>', 'MADE IN VIETNAM', 120000, '[{"name": "cổ", "value": "91-97 99-104 107-114 124-127 127-135 137-145"}, {"name": "Tay áo", "value": "84 86 89 91 94 97"}, {"name": "Ngực", "value": "76, 79 81, 84, 86 91, 97 102, 107 112 117"}, {"name": "Hông", "value": "91-97 97-102 107, 112 117, 122 127 132"}, {"name": "Chiều dài ống quần", "value": "S: 76 R: 81 L: 86"}]'::jsonb, 32, 0, TRUE, '2026-10-23T17:14:20.042567+07:00', '2026-10-23T17:14:20.042567+07:00'),
	(19, 223, 'Áo mưa balo 30-50L Ryder Rucksack Raincover M F1002 - 6699', 'ao-mua-balo-30-50l-ryder-rucksack-raincover-m-f1002-6699', 'Áo mưa balo 30-50L Ryder Rucksack Raincover M F1002 - 6699 là trang bị không thể thiếu dành cho những người đam mê du lịch khi tới những nơi có khí hậu mưa và ẩm ướt.', '<div> <div><strong>Ryder</strong> là một thương hiệu outdoor nổi tiếng thuộc sở hữu của tập đoàn Ryder ở Trung Quốc được thành lập vào năm 2009 chuyên cung cấp các thiết bị ngoài trời cho thị trường cao cấp trên thế giới một cách chuyên nghiệp. Các sản phẩm chính của Ryder bao gồm: lều, túi ngủ, balo, bếp dã ngoại, túi khô, nệm, ... được xuất khẩu sang các nước Bắc Mỹ, Châu Âu, Nhật Bản và các quốc gia, khu vực khác. Tất cả các sản phẩm của Ryder đều được sản xuất theo yêu cầu tiêu chuẩn như CE, FDA. Bên cạnh những tiêu chuẩn này, Ryder còn chú trọng đến sự hài lòng của các khách hàng, bởi khách hàng là người tiêu dùng đầu tiên. Và cho đến ngày nay, thương hiệu Ryder đã dành được danh tiếng và nhận được sự đánh giá cao từ khách hàng toàn cầu.<br />  </div> <div><img alt="THUONG-HIEU-RYDER_Campvivo_VN" height="261" src="https://wetrek.vn/pic/Product/hoanghien150993&#64;gmail.com/images/THUONG-HIEU-RYDER_Campvivo_VN.jpg" width="630" /></div>  <br /> <strong>Áo mưa balo 30-50L Ryder Rucksack Raincover M F1002 - 6699</strong> là trang bị không thể thiếu dành cho những người đam mê du lịch, dã ngoại khi tới những vùng đất có khí hậu ẩm ướt mưa nhiều. Sản phẩm được thiết kế với vật liệu chuyên dụng, kín đáo, bảo vệ balo của người dùng khỏi các trận mưa bất chợt, giữ cho hành trang luôn luôn khô ráo.</div> <ul><li>Áo mưa balo có lỗ thông hơi dưới đáy giúp thông khí, tránh cho balo bị hấp hơi khi sử dụng trong thời gian dài.</li><li>Làm từ vải PU chống nước tuyệt đối, an toàn ngay cả với những trận mưa trên 3000 mm.</li><li>Mép áo mưa có dây chun ôm sát balo.</li></ul> <div> </div> <div>Xem thêm các sản phẩm<strong> <a href="/categories/phu-kien-balo-tui" rel="nofollow">Phụ kiện Balo – Túi</a> </strong>tại <strong><a href="/categories/phu-kien-balo-tui" rel="nofollow">Campvivo.VN</a></strong></div>', 'RYDER', 139300, '[{"name": "Xuất xứ", "value": "Chính hãng"}, {"name": "Màu sắc", "value": "Xanh, Cam, Đỏ, Đen"}, {"name": "Chất liệu", "value": "Vải nylon phủ PU chống nước 3000m"}, {"name": "Trọng lượng", "value": "200g"}, {"name": "Thể tích ba lô phù hợp", "value": "30 - 50L"}, {"name": "Sản phẩm bao gồm", "value": "Áo mưa balo 30-50L Ryder Rucksack Raincover M F1002 - 6699"}]'::jsonb, 31, 0, TRUE, '2026-10-23T17:14:20.576749+07:00', '2026-10-23T17:14:20.576749+07:00'),
	(20, 34, 'Áo phao cứu sinh người lớn Coleman 2000023531', 'ao-phao-200023531', 'Áo phao cứu sinh người lớn Coleman 2000023531, vỏ nylon bền + xốp PE nổi, 3 dây đai điều chỉnh, phù hợp người trên 41kg.', '<div> <h2>Áo phao cứu sinh người lớn Coleman 2000023531</h2> <p>Áo phao Coleman 2000023531 là áo phao cứu sinh dành cho người lớn, thiết kế đơn giản, dễ mặc và ôm người — phù hợp cho các hoạt động dưới nước.</p> <p>Phần vỏ nylon bền kết hợp lõi xốp PE cho lực nổi ổn định, cùng hệ dây đai điều chỉnh giúp áo bám chắc, không bị xô lệch khi xuống nước.</p> <h3>Điểm nổi bật</h3> <ul><li>Vỏ nylon bền chắc, lõi xốp PE cho lực nổi ổn định.</li><li>3 dây đai điều chỉnh giúp ôm sát và vừa nhiều dáng người.</li><li>Thiết kế hở hai bên sườn, thoáng và dễ vận động.</li><li>Phù hợp người lớn trên khoảng 41kg, vòng ngực ~76–132cm.</li><li>Dễ mặc/cởi nhanh, phù hợp cả người mới.</li></ul> <h3>Thông số kỹ thuật</h3> <ul><li>Model: Coleman 2000023531</li><li>Đối tượng: Người lớn trên khoảng 41 kg</li><li>Vòng ngực phù hợp: khoảng 76 – 132 cm</li><li>Chất liệu: Vỏ nylon, lõi xốp PE</li><li>Thương hiệu: Coleman</li></ul> <h3>Phù hợp với</h3> <p>Chèo thuyền, kayak, SUP, câu cá, đi tàu, bơi ở hồ/biển và các hoạt động dưới nước.</p> <h3>Bảo quản</h3> <p>Xả nước sạch sau khi dùng (nhất là nước biển), phơi khô hoàn toàn nơi thoáng mát trước khi cất; không phơi nắng gắt kéo dài và không giặt máy.</p> </div>', 'COLEMAN', 1799000, '[]'::jsonb, 47, 0, TRUE, '2026-10-23T17:14:20.890148+07:00', '2026-10-23T17:14:20.890148+07:00'),
	(21, 137, 'Áo thun ngắn tay nữ Gothiar Active', 'ao-thun-ngan-tay-nu-gothiar-active', 'Áo thun dã ngoại Gothiar Active được thiết kế đặc biệt để đáp ứng nhu cầu của những người yêu thích hoạt động thể thao và dã ngoại. Với chất liệu polyester chất lượng cao, thấm hút mồ hôi tốt và thoáng khí, giúp bạn thoải mái trong mọi hoạt động.', '<p>Áo thun dã ngoại Gothiar Active được thiết kế đặc biệt để đáp ứng nhu cầu của những người yêu thích hoạt động thể thao và dã ngoại. Với chất liệu polyester chất lượng cao, thấm hút mồ hôi tốt và thoáng khí, giúp bạn thoải mái trong mọi hoạt động.</p> <p><img alt="" height="1599" loading="lazy" src="https://wetrek.vn/pic/products/images/20230517_141321.jpg" width="1600" /></p> <h1><strong>Đặc điểm nổi bật của áo thun Gothiar Active:</strong></h1> <h2><strong>1. Độ co giãn tốt và thoải mái</strong></h2> <p>Chất liệu polyester có độ co giãn linh hoạt, giúp áo thun Gothiar Active ôm sát cơ thể một cách tự nhiên và thoải mái. Điều này cho phép bạn linh hoạt vận động trong mọi hoạt động thể thao mà không gặp khó khăn.</p> <h2><strong>2. Chống nhăn và bền màu</strong></h2> <p>Polyester là một chất liệu rất chống nhăn, giúp áo thun Gothiar Active luôn giữ được hình dáng ban đầu ngay cả sau khi giặt và sấy. Bạn không cần phải lo lắng về việc áo sẽ nhăn nhúm và mất kiểu dáng sau một thời gian sử dụng. Đồng thời, chất liệu polyester cũng giữ màu sắc của áo thun không bị phai nhoà, cho phép bạn luôn tự tin diện áo thun với sắc màu tươi sáng.</p> <h2><strong>3. Thấm hút mồ hôi tốt</strong></h2> <p>Áo thun Gothiar Active được làm từ chất liệu polyester có khả năng thấm hút mồ hôi tốt. Điều này giúp bạn luôn cảm thấy khô ráo và thoải mái trong suốt thời gian hoạt động. Áo thun có khả năng tạo sự thông thoáng, cho phép không khí lưu thông và giữ cho cơ thể luôn mát mẻ.</p> <h1><strong>Câu hỏi thường gặp (FAQs)</strong></h1> <ol><li> <p><strong>Làm thế nào để bảo quản áo thun polyester?</strong></p> <ul><li> <p>Để bảo quản áo thun polyester, bạn nên giặt áo với nước lạnh hoặc ấm, không sử dụng chất tẩy mạnh, và tránh việc sử dụng máy sấy.</p> </li></ul> </li><li> <p><strong>Tôi có thể mặc áo thun polyester khi tham gia hoạt động thể thao không?</strong></p> <ul><li> <p>Có, áo thun polyester là lựa chọn tuyệt vời cho hoạt động thể thao, vì chất liệu này có khả năng thấm hút mồ hôi tốt và độ co giãn linh hoạt.</p> </li></ul> </li><li> <p><strong>Áo thun polyester phù hợp với da nhạy cảm không?</strong></p> <ul><li> <p>Chất liệu polyester không gây kích ứng da và thường không gây khó chịu cho da nhạy cảm. Tuy nhiên, nếu bạn có da rất nhạy cảm, nên thử mặc thử trước khi quyết định mua.</p> </li></ul> </li></ol>', 'GOTHIAR', 296000, '[{"name": "Xuất xứ", "value": "Việt Nam"}, {"name": "Chất liệu", "value": "75% Polyester,25% Cotton"}, {"name": "Bao gồm", "value": "Áo thun ngắn tay Gothiar Active"}]'::jsonb, 123, 0, TRUE, '2026-10-23T17:14:22.900408+07:00', '2026-10-23T17:14:22.900408+07:00'),
	(22, 188, 'Áo sơ mi dài tay mau khô nam Ktom K128', 'ao-so-mi-dai-tay-mau-kho-nam-ktom-k128', 'Áo chống nắng KTOM được làm bằng chất liệu vải nhanh khô với công nghệ OMNI-SHADE ® cản tia UV (hay còn gọi là tia cực tím) làm cho bạn an toàn hơn khi đi ngoài trời.', '<p>Áo chống nắng KTOM được làm bằng chất liệu vải nhanh khô với công nghệ OMNI-SHADE ® cản tia UV (hay còn gọi là tia cực tím) làm cho bạn an toàn hơn khi đi ngoài trời. Với tác dụng thoáng mát và cực thoáng nên áo thường được sử dụng cho các hoạt động dã ngoại như câu cá, đi bộ. leo núi&#x2026;</p> <ul><li>Công nghệ Ommi-Wick, thoát hơi nhanh, rất nhanh khô, mang lại cảm giác thoáng mát</li><li>Công nghệ Omni-Shade chống tia cực tím UPF 50</li><li>Khe thông gió phía sau lưng giúp thoát hơi tốt, làm cho bạn cảm thấy mát hơn khi đi ngoài nắng</li><li>Áo có 2 túi trước ngực, một túi có khóa kéo</li><li>Áo dài tay nên có thêm 1 chiếc đai ở giữa tay áo, để khi xắn tay lên, gài lại mà không bị tuột</li><li>Chât liệu: 100% polyester</li></ul> <p><img alt="Áo sơ mi dài tay mau khô nam Ktom K128" height="1000" loading="lazy" src="https://wetrek.vn/pic/products/images/bcffdf4cdeda91b014272fb492ec8cf7.jpg" width="1000" /></p> <p><img alt="" height="1000" loading="lazy" src="https://wetrek.vn/pic/products/images/c99896448840cb422c7cbc551443eb3e.jpg" width="1000" /></p>', 'KTOM', 460000, '[]'::jsonb, 1, 0, TRUE, '2026-10-23T17:14:24.10527+07:00', '2026-10-23T17:14:24.10527+07:00'),
	(23, 245, 'Áo mưa đoàn loại tốt', 'ao-mua-doan', 'Áo mưa đoàn bảo vệ bạn khỏi thời tiết mưa nắng thất thường trong những chuyến leo núi, đảm bảo trải nghiệm ngoài trời an toàn trong thời tiết khắc nghiệt nhất.', '<div> <p><strong>Hướng dẫn mua hàng trực tuyến: </strong>Chỉ với 3 bước mua hàng đơn giản, sản phẩm bạn yêu thích sẽ có mặt tại nhà bạn sau 2-3 ngày làm việc. </p> <p><strong>Bước 1:</strong>  Sau khi tìm được sản phẩm yêu thích, bạn có thể chọn số lượng, màu sắc và click vào nút <strong>MUA NGAY</strong> (nếu bạn muốn mua một sản phẩm) hoặc click vào nút <strong>THÊM VÀO GIỎ</strong> (xem và chọn thêm sản phẩm khác).</p> <p><strong>Bước 2:</strong> Cập nhật giỏ hàng: Bạn có thể thay đổi số lượng sản phẩm cần mua bằng cách điền vào ô số lượng. Rồi tiếp tục ấn vào nút <strong>MUA NGAY</strong>. </p> <p><strong>Bước 3:</strong> Bạn hãy điền đầy đủ thông tin theo hướng dẫn, chọn hình thức thanh toán, sau đó click <strong>GỬI ĐƠN HÀNG</strong></p> <p>Ngoài ra, Bạn có thể tiếp tục mua những sản phẩm khác bằng cách click vào dòng Tiếp tục mua hàng.</p> <p>Khi đơn hàng đã được gửi thành công, team Campvivo sẽ liên lạc với bạn để xác nhận thông tin và tiến hành thực hiện giao dịch.</p> </div> <ul><li>Miễn phí giao hàng toàn quốc với đơn hàng trên 500.000 (Tối đa 50k) (trừ những sản phẩm thuộc nhóm Đồ Dùng Chung, hàng ưu đãi về giá, outlet, hàng cồng kềnh: Kayak, ...)</li><li>Đổi trả hàng trong vòng 14 ngày.</li></ul> <div> </div>', 'Khác', 25000, '[]'::jsonb, 0, 0, TRUE, '2026-10-23T17:14:24.977369+07:00', '2026-10-23T17:14:24.977369+07:00'),
	(24, 189, 'Áo thun dài tay nam Gothiar Active', 'ao-thun-dai-tay-nam-gothiar-active-xanh-than', 'Áo phông là một trong những loại áo thường được sử dụng trong thời trang hàng ngày. Nó có thiết kế đơn giản, dễ mặc và phù hợp với nhiều hoàn cảnh khác nhau. Với sự phát triển của công nghệ vải, chất liệu áo phông ngày càng đa dạng, tạo ra sự thoải mái và tiện ích cho người mặc.', '<p>Áo thun dã ngoại Gothiar Active được thiết kế đặc biệt để đáp ứng nhu cầu của những người yêu thích hoạt động thể thao và dã ngoại. Với chất liệu polyester chất lượng cao, thấm hút mồ hôi tốt và thoáng khí, giúp bạn thoải mái trong mọi hoạt động.</p> <p><img alt="Áo thun dài tay nam Gothiar Active" height="1000" loading="lazy" src="https://wetrek.vn/pic/products/images/638209668014145798.jpg.ashx" width="1000" /></p> <h1><strong>Đặc điểm nổi bật của áo thun Gothiar Active:</strong></h1> <h2><strong>1. Độ co giãn tốt và thoải mái</strong></h2> <p>Chất liệu polyester có độ co giãn linh hoạt, giúp áo thun Gothiar Active ôm sát cơ thể một cách tự nhiên và thoải mái. Điều này cho phép bạn linh hoạt vận động trong mọi hoạt động thể thao mà không gặp khó khăn.</p> <h2><strong>2. Chống nhăn và bền màu</strong></h2> <p>Polyester là một chất liệu rất chống nhăn, giúp áo thun Gothiar Active luôn giữ được hình dáng ban đầu ngay cả sau khi giặt và sấy. Bạn không cần phải lo lắng về việc áo sẽ nhăn nhúm và mất kiểu dáng sau một thời gian sử dụng. Đồng thời, chất liệu polyester cũng giữ màu sắc của áo thun không bị phai nhoà, cho phép bạn luôn tự tin diện áo thun với sắc màu tươi sáng.</p> <h2><strong>3. Thấm hút mồ hôi tốt</strong></h2> <p>Áo thun Gothiar Active được làm từ chất liệu polyester có khả năng thấm hút mồ hôi tốt. Điều này giúp bạn luôn cảm thấy khô ráo và thoải mái trong suốt thời gian hoạt động. Áo thun có khả năng tạo sự thông thoáng, cho phép không khí lưu thông và giữ cho cơ thể luôn mát mẻ.</p> <h1><strong>Câu hỏi thường gặp (FAQs)</strong></h1> <ol><li> <p><strong>Làm thế nào để bảo quản áo thun polyester?</strong></p> <ul><li> <p>Để bảo quản áo thun polyester, bạn nên giặt áo với nước lạnh hoặc ấm, không sử dụng chất tẩy mạnh, và tránh việc sử dụng máy sấy.</p> </li></ul> </li><li> <p><strong>Tôi có thể mặc áo thun polyester khi tham gia hoạt động thể thao không?</strong></p> <ul><li> <p>Có, áo thun polyester là lựa chọn tuyệt vời cho hoạt động thể thao, vì chất liệu này có khả năng thấm hút mồ hôi tốt và độ co giãn linh hoạt.</p> </li></ul> </li><li> <p><strong>Áo thun polyester phù hợp với da nhạy cảm không?</strong></p> <ul><li> <p>Chất liệu polyester không gây kích ứng da và thường không gây khó chịu cho da nhạy cảm. Tuy nhiên, nếu bạn có da rất nhạy cảm, nên thử mặc thử trước khi quyết định mua.</p> </li></ul> </li></ol>', 'GOTHIAR', 329000, '[{"name": "Xuất xứ", "value": "Việt Nam"}, {"name": "Chất liệu", "value": "75% Polyester,25% Cotton"}, {"name": "Màu sắc", "value": "Xanh than, Ghi, Đen,Tím"}, {"name": "Bao gồm", "value": "Áo thun dài tay nam Gothiar Active"}]'::jsonb, 184, 0, TRUE, '2026-10-23T17:14:25.155143+07:00', '2026-10-23T17:14:25.155143+07:00'),
	(25, 60, 'Áo dài tay Gothiar Comfort Sweatshirt', 'ao-dai-tay-gothiar-comfort-sweatshirt', 'Áo dài tay Gothiar Comfort Sweatshirt - Với thiết kế đơn giản, form dáng vừa vặn, chất liệu vải dày dặn, ấm áp, giúp mang lại sự năng động, trẻ trung, ấm áp cho người mặc', '<p>Áo dài tay Gothiar Comfort Sweatshirt là một trong những sản phẩm mới nhất của thương hiệu thời trang Gothiar. Với thiết kế đơn giản, form dáng vừa vặn, chất liệu vải <strong>Polyester</strong> dày dặn, ấm áp, áo là sự lựa chọn hoàn hảo cho mọi người yêu thích phong cách trẻ trung, năng động.</p> <p><img alt="" height="1200" loading="lazy" src="https://wetrek.vn/pic/general/images/ao-hoodie-co-mu-gothiar-10531-6.jpg" width="1200" /></p> <p><strong>Form dáng regular vừa vặn, thoải mái vận động</strong></p> <p>Áo dài tay Gothiar Comfort Sweatshirt có form dáng regular, vừa vặn với người mặc, không quá ôm cùng không quá rộng. Thiết kế này giúp đảm bảo sự thoải mái cho người mặc khi vận động, di chuyển.</p> <p><strong>Chất liệu vải dày dặn, ấm áp</strong></p> <p>Áo được làm từ chất liệu vải <strong>Polyester</strong> dày dặn, có khả năng giữ ấm tốt. Chất vải mềm mại, mang lại cảm giác thoải mái, dễ chịu cho người mặc.</p> <p><img alt="" height="1200" loading="lazy" src="https://wetrek.vn/pic/general/images/ao-hoodie-co-mu-gothiar-nau%283%29.jpg" width="1200" /></p> <p><strong>Thiết kế áo tay dài ấm áp</strong></p> <p>Thiết kế áo tay dài giúp giữ ấm cơ thể hiệu quả, phù hợp với thời tiết se lạnh. Áo có cổ tròn,  giúp tạo phong cách ấn tượng cho người mặc.</p> <p><strong>Logo life republic ấn tượng</strong></p> <p>Phần ngực áo có logo <strong>life republic</strong> nổi bật, tạo điểm nhấn ấn tượng cho tổng thể thiết kế. Logo được làm tỉ mỉ, sắc nét, mang lại vẻ đẹp tinh tế, sang trọng cho áo.</p> <p><img alt="" height="1200" loading="lazy" src="https://wetrek.vn/pic/general/images/ao-hoodie-co-mu-gothiar-trang-Campvivo%286%29.jpg" width="1200" /></p> <p><strong>Màu sắc đa dạng</strong></p> <p>Áo dài tay Gothiar Comfort Sweatshirt có nhiều màu sắc đa dạng, phù hợp với mọi phong cách thời trang. Khách hàng có thể thoải mái lựa chọn màu phù hợp với sở thích và cá tính của mình.</p> <p><strong>Phối đồ đa dạng</strong></p> <p>Áo dài tay Gothiar Comfort Sweatshirt mang phong cách đơn giản nên có thể dễ dàng phối đồ cùng nhiều loại quần áo khác nhau. Các chàng trai có thể kết hợp áo với quần jean, quần short, quần kaki,... để tạo nên những set đồ năng động, trẻ trung. Áo cũng có thể được mặc để đi chơi, đi làm, đi học,...</p> <p>Mua ngay các sản phẩm <a href="/categories/ao-ni-hoodie" rel="nofollow"><strong>Áo dài tay</strong></a> tại <strong><a href="/" rel="nofollow">campvivo.vn</a></strong></p>', 'GOTHIAR', 439000, '[{"name": "Xuất xứ", "value": "Chính hãng"}, {"name": "Chất liệu", "value": "95% Polyester và 5% Spandex"}, {"name": "Màu sắc", "value": "Đen, nâu, xanh lá, trắng, vàng"}]'::jsonb, 114, 0, TRUE, '2026-10-23T17:14:25.63932+07:00', '2026-10-23T17:14:25.63932+07:00'),
	(26, 189, 'Áo thun ngắn tay nam Gothiar AT Dry', 'ao-thun-ngan-tay-nam-gothiar-at-dry', 'Áo thun là một trong những loại áo thường được sử dụng trong thời trang hàng ngày. Nó có thiết kế đơn giản, dễ mặc và phù hợp với nhiều hoàn cảnh khác nhau. Với sự phát triển của công nghệ vải, chất liệu áo thun ngày càng đa dạng, tạo ra sự thoải mái và tiện ích cho người mặc.', '<p>Áo thun là một trong những loại áo thường được sử dụng trong thời trang hàng ngày. Nó có thiết kế đơn giản, dễ mặc và phù hợp với nhiều hoàn cảnh khác nhau. Với sự phát triển của công nghệ vải, chất liệu áo thun ngày càng đa dạng, tạo ra sự thoải mái và tiện ích cho người mặc.</p> <p><img alt="" height="2560" loading="lazy" src="https://wetrek.vn/pic/products/images/ao-thun-gothiar-atdry-10469%20%283%29.jpg" width="1920" /></p> <p>Một trong những chất liệu phổ biến được sử dụng cho áo thun là 75% polyester và 25% spandex. Polyester là loại sợi nhân tạo, có khả năng chống nhăn, bền màu và khó bị co rút. Trong khi đó, spandex là loại sợi co giãn, có khả năng đàn hồi và giúp áo phông ôm sát cơ thể.</p> <p>Việc sử dụng chất liệu này cho áo phông mang lại nhiều lợi ích cho người mặc. Đầu tiên, áo phông được làm từ chất liệu này có độ co giãn tốt, giúp người mặc dễ dàng vận động và thoải mái trong mọi hoàn cảnh. Thứ hai, chất liệu polyester giúp áo thun không nhăn và bền màu, cho phép người mặc giữ nguyên được hình dáng và màu sắc của áo theo thời gian. Thứ ba, áo phông được làm từ chất liệu này cũng có khả năng thấm hút mồ hôi tốt, giúp người mặc cảm thấy khô ráo và thoải mái trong suốt thời gian sử dụng.</p> <p><img alt="" height="2560" loading="lazy" src="https://wetrek.vn/pic/products/images/ao-thun-gothiar-atdry-10469%20%282%29.jpg" width="1920" /><img alt="" height="2560" loading="lazy" src="https://wetrek.vn/pic/products/images/ao-thun-gothiar-atdry-10469%20%281%29.jpg" width="1920" /></p>', 'GOTHIAR', 323000, '[{"name": "Xuất xứ", "value": "Việt Nam"}, {"name": "Chất liệu", "value": "75% Polyester,25% Cotton"}, {"name": "Bao gồm", "value": "Áo thun ngắn tay nam Gothiar AT Dry"}]'::jsonb, 132, 0, TRUE, '2026-10-23T17:14:25.862864+07:00', '2026-10-23T17:14:25.862864+07:00'),
	(27, 206, 'Ba lô 15L Coleman CBB0011BK - Đen', 'ba-lo-15l-coleman-cbb0011bk-den', 'Ba lô 15L Coleman CBB0011BK - Đen được làm bằng vải polyester rất bền, kiểu dáng thời trang năng động khi đi chơi, đi học hay đi du lịch dã ngoại trong ngày.', '<div> <div>Du lịch, khám phá các vùng miền luôn là sở thích, niềm đam mê của những con người năng động, ưa mạo hiểm, thích tìm tòi cái mới. Được lăn lộn trên các cung đường dài, chinh phục những vùng trời mới hay rong ruổi ngắm cảnh trên những vùng quê yên bình, tìm hiểu phong tục của người bản địa luôn là niềm hạnh phúc của họ. Nhưng để chuyến đi thực sự ý nghĩa và an toàn hàng đầu thì hành trang không thể thiếu là chiếc <a href="/categories/balo" rel="nofollow">balo du lịch</a> với đầy đủ vật dụng cần thiết.<br />  </div> <div> <div></div> <div><br /> <strong>Coleman là hãng sản xuất <a href="/" rel="nofollow">đồ outdoor</a> nổi tiếng trên thế giới đi lên từ các sản phẩm đèn chiếu sáng, đến nay Coleman đã có chỗ đứng vững chắc trên thị trường outdoor thế giới với nhiều sản phẩm phục vụ nhu cầu du lịch, dã ngoại, và các hoạt động ngoài trời của khách hàng.</strong><br /> <br /> <strong>Campvivo.VN</strong> xin giới thiệu sản phẩm: <strong>Ba lô 15L Coleman CBB0011BK - Đen</strong></div> <ul><li>Balo được thiết kế siêu nhẹ, lớp đệm sau balo rất êm ái và thông thoáng, giúp đeo balo lâu không bị mỏi</li><li>Dây đai trước ngực giúp cố định balo, giảm sức nặng lên vai</li><li>Balo gồm 2 ngăn chính lớn và nhiều ngăn phụ bên trong, thêm 2 túi sườn đựng bình nước, bình giữ nhiệt</li><li>Viền balo có tính năng phản quang.</li><li>Kích thước: 24 x 45 x 14 cm</li><li>Thể tích: 15 lít</li><li>Trọng lượng: 345g</li><li>Màu sắc: Đen</li></ul> <strong>ĐẶC TÍNH:</strong><br />   Thương hiệuColemanXuất xứ Loại khung trợ lựcKhôngKích thước24 x 45 x 14 cmTrọng lượng345 gThể tích15 LMàu sắcĐenChất liệuPolyesterSố ngăn/túi2 ngăn chính lớn và nhiều ngăn phụÁo mưa baloKhôngSản phẩm bao gồmBa lô 15L Coleman CBB0011BK - ĐenPhù hợp sử dụngDu lịch, dã ngoại trong ngày hay đi học, đi làmSKU3650 </div> </div> <p>Xem thêm các sản phẩm <a href="/brands/balo-du-lich-coleman" rel="nofollow"><strong>Balo du lịch Coleman</strong></a> trại <a href="/brands/balo-du-lich-coleman" rel="nofollow"><strong>Campvivo.VN</strong></a></p>', 'COLEMAN', 1499000, '[]'::jsonb, 44, 0, TRUE, '2026-10-23T17:14:26.668805+07:00', '2026-10-23T17:14:26.668805+07:00'),
	(28, 246, 'Áo thun ngắn tay Gothiar Active', 'ao-thun-ngan-tay-gothiar-active', 'Áo thun là một trong những loại áo thường được sử dụng trong thời trang hàng ngày. Nó có thiết kế đơn giản, dễ mặc và phù hợp với nhiều hoàn cảnh khác nhau. Với sự phát triển của công nghệ vải, chất liệu áo thun ngày càng đa dạng, tạo ra sự thoải mái và tiện ích cho người mặc.', '<p>Áo thun là một trong những loại áo thường được sử dụng trong thời trang hàng ngày. Nó có thiết kế đơn giản, dễ mặc và phù hợp với nhiều hoàn cảnh khác nhau. Với sự phát triển của công nghệ vải, chất liệu áo thun ngày càng đa dạng, tạo ra sự thoải mái và tiện ích cho người mặc.</p> <p><img alt="Áo thun ngắn tay Gothiar Active" height="1000" loading="lazy" src="https://wetrek.vn/pic/products/images/Web04-10358%20%C4%91en.jpg" width="1000" /></p> <p>Một trong những chất liệu phổ biến được sử dụng cho áo thun là 75% polyester và 25% spandex. Polyester là loại sợi nhân tạo, có khả năng chống nhăn, bền màu và khó bị co rút. Trong khi đó, spandex là loại sợi co giãn, có khả năng đàn hồi và giúp áo phông ôm sát cơ thể.</p> <p>Việc sử dụng chất liệu này cho áo phông mang lại nhiều lợi ích cho người mặc. Đầu tiên, áo phông được làm từ chất liệu này có độ co giãn tốt, giúp người mặc dễ dàng vận động và thoải mái trong mọi hoàn cảnh. Thứ hai, chất liệu polyester giúp áo thun không nhăn và bền màu, cho phép người mặc giữ nguyên được hình dáng và màu sắc của áo theo thời gian. Thứ ba, áo phông được làm từ chất liệu này cũng có khả năng thấm hút mồ hôi tốt, giúp người mặc cảm thấy khô ráo và thoải mái trong suốt thời gian sử dụng.</p> <p><img alt="" height="1000" loading="lazy" src="https://wetrek.vn/pic/products/images/Web02-10358%20%C4%91en.jpg" width="1000" /></p>', 'GOTHIAR', 296000, '[{"name": "Xuất xứ", "value": "Việt Nam"}, {"name": "Chất liệu", "value": "75% Polyester,25% Cotton"}, {"name": "Màu sắc", "value": "Xanh than, Ghi, Đen,Xanh rêu nhạt, Ghi xám"}, {"name": "Bao gồm", "value": "Áo thun ngắn tay Gothiar Active"}]'::jsonb, 448, 0, TRUE, '2026-10-23T17:14:27.055422+07:00', '2026-10-23T17:14:27.055422+07:00'),
	(29, 206, 'Ba lô 15L Coleman CBB0011BE - Tím', 'ba-lo-15l-coleman-cbb0011be-tim', 'Ba lô 15L Coleman CBB0011BE - Tím được làm bằng vải polyester rất bền, kiểu dáng thời trang năng động khi đi chơi, đi học hay đi du lịch dã ngoại trong ngày.', '<div>Du lịch, khám phá các vùng miền luôn là sở thích, niềm đam mê của những con người năng động, ưa mạo hiểm, thích tìm tòi cái mới. Được lăn lộn trên các cung đường dài, chinh phục những vùng trời mới hay rong ruổi ngắm cảnh trên những vùng quê yên bình, tìm hiểu phong tục của người bản địa luôn là niềm hạnh phúc của họ. Nhưng để chuyến đi thực sự ý nghĩa và an toàn hàng đầu thì hành trang không thể thiếu là chiếc <a href="/categories/balo" rel="nofollow">balo du lịch</a> với đầy đủ vật dụng cần thiết.<br />  </div> <div> <div></div> <div><br /> <strong>Coleman là hãng sản xuất <a href="/" rel="nofollow">đồ outdoor</a> nổi tiếng trên thế giới đi lên từ các sản phẩm đèn chiếu sáng, đến nay Coleman đã có chỗ đứng vững chắc trên thị trường outdoor thế giới với nhiều sản phẩm phục vụ nhu cầu du lịch, dã ngoại, và các hoạt động ngoài trời của khách hàng.</strong><br /> <br /> <strong>Campvivo.VN</strong> xin giới thiệu sản phẩm: <strong>Ba lô 15L Coleman CBB0011BE - Tím</strong></div> <ul><li>Balo được thiết kế siêu nhẹ, lớp đệm sau balo rất êm ái và thông thoáng, giúp đeo balo lâu không bị mỏi</li><li>Dây đai trước ngực giúp cố định balo, giảm sức nặng lên vai</li><li>Balo gồm 2 ngăn chính lớn và nhiều ngăn phụ bên trong, thêm 2 túi sườn đựng bình nước, bình giữ nhiệt</li><li>Viền balo có tính năng phản quang.</li><li>Kích thước: 24 x 45 x 14 cm</li><li>Thể tích: 15 lít</li><li>Trọng lượng: 345g</li><li>Màu sắc: Tím</li></ul> <strong>ĐẶC TÍNH:</strong><br />   Thương hiệuColemanXuất xứ Loại khung trợ lựcKhôngKích thước24 x 45 x 14 cmTrọng lượng345 gThể tích15 LMàu sắcTímChất liệuPolyesterSố ngăn/túi2 ngăn chính lớn và nhiều ngăn phụÁo mưa baloKhôngSản phẩm bao gồmBa lô 15L Coleman CBB0011BE - TímPhù hợp sử dụngDu lịch, dã ngoại trong ngày hay đi học, đi làmSKU3647 </div> <p>Xem thêm các sản phẩm <a href="/brands/balo-du-lich-coleman" rel="nofollow"><strong>Balo du lịch Coleman</strong></a> trại <a href="/brands/balo-du-lich-coleman" rel="nofollow"><strong>Campvivo.VN</strong></a></p>', 'COLEMAN', 1499000, '[]'::jsonb, 0, 0, TRUE, '2026-10-23T17:14:27.691278+07:00', '2026-10-23T17:14:27.691278+07:00'),
	(30, 221, 'Ba lô 30L Coleman CBB0031BK - Đen', 'ba-lo-30l-coleman-cbb0031bk-den', 'Ba lô 30L Coleman CBB0031BK - Đen chính hãng, giá tốt nhất tại Campvivo.VN. Campvivo tự hào là nhà phân phối sản phẩm Coleman chính hãng tại Việt Nam. Hotline 1900 0000.', '<div> <div> <div><strong>Coleman</strong> là hãng sản xuất đồ outdoor nổi tiếng thế giới, bắt đầu các sản phẩm đèn chiếu sáng. Theo thời gian, Coleman dần dần có chỗ đứng vững chắc trên thị trường với nhiều sản phẩm phục vụ du lịch - dã ngoại và các hoạt động ngoài trời. Các sản phẩm của Coleman rất đa dạng, từ đèn chiếu sáng, thùng đá giữ nhiệt, đệm hơi, balo, phụ kiện cho tới những dụng cụ sinh tồn, dụng cụ nhà bếp cần thiết. Ngày này, các sản phẩm <strong>Coleman</strong> được phân phối rộng rãi khắp các châu lục, tại nhiều quốc gia trên thế giới.</div> <div> </div> <div> <div></div> </div> </div> <br /> <strong>Campvivo.VN</strong> xin giới thiệu sản phẩm: <strong>Ba lô 30L Coleman CBB0031BK - Đen</strong> <ul><li>Balo được thiết kế siêu nhẹ, lớp đệm sau balo rất êm ái và thông thoáng, giúp đeo balo lâu không bị mỏi</li><li>Dây đai trước ngực giúp cố định balo, giảm sức nặng lên vai</li><li>Balo gồm 2 ngăn chính lớn và nhiều ngăn phụ bên trong, thêm 2 túi bên hông đựng bình nước, bình giữ nhiệt</li><li>Viền balo có tính năng phản quang.</li></ul> <strong>ĐẶC TÍNH:</strong><br />   Thương hiệuColemanXuất xứ Màu sắcXanh dươngKích thước28 x 60 x 18 cmTrọng lượng630 gThể tích30 LChất liệuPolyesterSố ngăn5 ngăn (3 ngăn ngoài/2 ngăn trong)Sản phẩm bao gồmBa lô 30L Coleman CBB0031BK - Đen <br /> Xem thêm các sản phẩm <a href="/brands/balo-du-lich-coleman" rel="nofollow"><strong>Balo du lịch Coleman</strong></a> trại <strong><a href="/brands/balo-du-lich-coleman" rel="nofollow">Campvivo.VN</a></strong></div>', 'COLEMAN', 2199000, '[]'::jsonb, 13, 0, TRUE, '2026-10-23T17:14:27.852545+07:00', '2026-10-23T17:14:27.852545+07:00'),
	(31, 221, 'Ba lô 30L Coleman CBB0031BE - Tím', 'ba-lo-30l-coleman-cbb0031be-tim', 'Ba lô 30L Coleman CBB0031BE - Tím chính hãng, giá tốt nhất tại Campvivo.VN. Campvivo tự hào là nhà phân phối sản phẩm Coleman chính hãng tại Việt Nam. Hotline 1900 0000.', '<div> <div> <div><strong>Coleman</strong> là hãng sản xuất đồ outdoor nổi tiếng thế giới, bắt đầu các sản phẩm đèn chiếu sáng. Theo thời gian, Coleman dần dần có chỗ đứng vững chắc trên thị trường với nhiều sản phẩm phục vụ du lịch - dã ngoại và các hoạt động ngoài trời. Các sản phẩm của Coleman rất đa dạng, từ đèn chiếu sáng, thùng đá giữ nhiệt, đệm hơi, balo, phụ kiện cho tới những dụng cụ sinh tồn, dụng cụ nhà bếp cần thiết. Ngày này, các sản phẩm <strong>Coleman</strong> được phân phối rộng rãi khắp các châu lục, tại nhiều quốc gia trên thế giới.</div> <div> </div> <div> <div></div> </div> </div> <br /> <strong>Campvivo.VN</strong> xin giới thiệu sản phẩm: <strong>Ba lô 30L Coleman CBB0031BE - Tím</strong> <ul><li>Balo được thiết kế siêu nhẹ, lớp đệm sau balo rất êm ái và thông thoáng, giúp đeo balo lâu không bị mỏi</li><li>Dây đai trước ngực giúp cố định balo, giảm sức nặng lên vai</li><li>Balo gồm 2 ngăn chính lớn và nhiều ngăn phụ bên trong, thêm 2 túi bên hông đựng bình nước, bình giữ nhiệt</li><li>Viền balo có tính năng phản quang.</li></ul> <strong>ĐẶC TÍNH:</strong><br />   Thương hiệuColemanXuất xứ Màu sắcXanh dươngKích thước28 x 60 x 18 cmTrọng lượng630 gThể tích30 LChất liệuPolyesterSố ngăn5 ngăn (3 ngăn ngoài/2 ngăn trong)Sản phẩm bao gồmBa lô 30L Coleman CBB0031BE - Tím <br /> Xem thêm các sản phẩm <a href="/brands/balo-du-lich-coleman" rel="nofollow"><strong>Balo du lịch Coleman</strong></a> trại <strong><a href="/brands/balo-du-lich-coleman" rel="nofollow">Campvivo.VN</a></strong></div>', 'COLEMAN', 2199000, '[]'::jsonb, 7, 0, TRUE, '2026-10-23T17:14:28.840318+07:00', '2026-10-23T17:14:28.840318+07:00'),
	(32, 135, 'Áo sơ mi dài tay mau khô nam Gothiar Active', 'ao-so-mi-dai-tay-mau-kho-nam-gothiar-active', 'Làm bằng chất liệu vải nhanh khô với công nghệ đạt chuẩn UV50+ (hay còn gọi là tia cực tím) giúp cho bạn an toàn hơn khi đi ngoài trời.', '<p>Làm bằng chất liệu vải nhanh khô với công nghệ đạt chuẩn UV50&#43; (hay còn gọi là tia cực tím) giúp cho bạn an toàn hơn khi đi ngoài trời. Với tác dụng thoáng mát và cực thoáng nên áo thường được sử dụng cho các hoạt động dã ngoại như câu cá, đi bộ. leo núi&#x2026;</p> <p><img alt="Áo sơ mi dài tay mau khô nam Gothiar Active" height="1000" loading="lazy" src="https://wetrek.vn/pic/products/images/DSC05879.jpg" width="1000" /></p> <p><strong>Đặc điểm nổi bật:</strong></p> <ul><li>Công nghệ thoát hơi nhanh, rất nhanh khô, mang lại cảm giác thoáng mát</li><li>Công nghệ chống tia cực tím UPF 50</li><li>Áo có 3 túi trước ngực, 2 túi to cùng 1 túi con để đựng vật nhỏ như dụng cụ đa năng</li><li>Chât liệu: 100% polyester</li></ul> <p><img alt="" height="1000" loading="lazy" src="https://wetrek.vn/pic/products/images/DSC05866.jpg" width="1000" /></p>', 'GOTHIAR', 469000, '[{"name": "Xuất xứ", "value": "Việt Nam"}, {"name": "Màu sắc", "value": "Be,Đen,Xanh rêu"}, {"name": "Chất liệu", "value": "35% Polyester, 65% Cotton"}, {"name": "Sản phẩm bao gồm", "value": "Áo sơ mi dài tay mau khô nam Gothiar Active"}]'::jsonb, 84, 0, TRUE, '2026-10-23T17:14:29.618893+07:00', '2026-10-23T17:14:29.618893+07:00'),
	(33, 160, 'Ba lô giữ lạnh Coleman 2000030101 - 9352', 'ba-lo-giu-lanh-coleman-2000030101-9352', 'Ba lô giữ lạnh Coleman 2000030101 - 9352 Thiết kế dạng balo, không cần cầm nắm. Xốp bọt biển dày, giúp giữ lạnh lên đến 12h. Giữ nóng/lạnh cho thực phẩm, nước uống. Gấp gọn khi không sử dụng.Có nắp khóa kéo trên cùng, túi lưới bên dưới, dây đeo balo có thể điều chỉnh. Lớp lót bên trong kháng khuẩn, kháng mùi hôi, chống nấm mốc, chống rò rỉ.', '<p><strong>Coleman</strong> là hãng sản xuất đồ outdoor nổi tiếng thế giới, bắt đầu các sản phẩm đèn chiếu sáng. Theo thời gian, Coleman dần dần có chỗ đứng vững chắc trên thị trường với nhiều sản phẩm phục vụ <strong>du lịch - dã ngoại</strong> và các hoạt động ngoài trời. Các sản phẩm của Coleman rất đa dạng, từ đèn chiếu sáng, thùng đá giữ nhiệt, đệm hơi, balo, phụ kiện cho tới những dụng cụ sinh tồn, dụng cụ nhà bếp cần thiết. Ngày này, các sản phẩm Coleman được phân phối rộng rãi khắp các châu lục, tại nhiều quốc gia trên thế giới.<br />  </p> <div><img alt="thuong-hieu-coleman-campvivo.vn" height="215" loading="lazy" src="https://wetrek.vn/pic/products/images/thuong-hieu-coleman-Campvivo_vn.jpg" width="630" /><br />  </div> <div><strong>Campvivo.VN</strong> giới thiệu bạn sản phẩm <strong>Ba lô giữ lạnh Coleman 2000030101 - 9352<br /> <img alt="" loading="lazy" src="https://wetrek.vn/pic/products/images/balo-giu-lanh-coleman-2000030101-9352-Campvivo-vn3.jpg" /><br /> Đặc điểm nổi bật:</strong><br />   <div>Thiết kế dạng balo, không cần cầm nắm.</div> <div>Xốp bọt biển dày, giúp giữ lạnh lên đến 12h. Giữ nóng/lạnh cho thực phẩm, nước uống. Gấp gọn khi không sử dụng.Có nắp khóa kéo trên cùng, túi lưới bên dưới, dây đeo balo có thể điều chỉnh. Lớp lót bên trong đạt chuẩn FDA kháng khuẩn, kháng mùi hôi, chống nấm mốc, chống rò rỉ. </div> <br /> <strong>Thông số kỹ thuật:</strong> <ul><li>Dung tích: 20 lon</li><li>Thời gian giữ nhiệt: 12 tiếng</li><li>Kích thước: 33x25x13 cm (Khi thu gọn)</li></ul> </div> <p>Xem thêm các sản phẩm <a href="/categories/tui-giu-lanh-tui-giu-nhiet" rel="nofollow"><strong>Túi giữ lạnh – Túi giữ nhiệt</strong></a> tại <strong><a href="/" rel="nofollow">Campvivo.VN</a></strong></p>', 'COLEMAN', 1100000, '[]'::jsonb, 16, 0, TRUE, '2026-10-23T17:14:29.951418+07:00', '2026-10-23T17:14:29.951418+07:00'),
	(34, 140, 'Baga xe máy GIVI MR-MR5 Monorack - 5391', 'baga-xe-may-givi-mr-monorack-5391', 'Baga xe máy GIVI MR Monorack - 5391 là phụ kiện quan trọng sử dụng cùng thùng xe máy GIVI. Baga được sản xuất với dây chuyền công nghệ tiên tiến, kiểm tra chất lượng nghiêm ngặt, với tiêu chí an toàn đặt lên hàng đầu.', '<div><strong>GIVI</strong> là thương hiệu hàng đầu thế giới về <strong>đồ motor</strong>, <strong>xe máy</strong>, <strong>phụ kiện xe máy</strong> được nhiều người biết đến trên toàn thế giới kể từ khi được thành lập cách đây hơn 35 năm tại Ý bởi Giuseppe Visenzi - một tay đua lừng danh những năm 60, đã đoạt giải 3 vô địch thế giới môn đua xe máy dung tích 350cc vào năm 1969. Vào cuối năm 2004, <strong>GIVI Concessionaires Vietnam</strong> được thành lập ở Bình Dương nhằm đưa các phụ kiện xe máy, đồ motor tới tay người tiêu dùng Việt. GIVI có hệ thống phân phối nhanh chóng, hợp lý và hiệu quả đã xây dựng nên niềm tin và sự hài lòng tuyệt đối của khách hàng đối với thương hiệu này.</div> <div><img alt="Thung-xe-may-GIVI-Campvivo_VN" height="286" src="https://wetrek.vn/pic/Product/hoanghien150993&#64;gmail.com/images/Thung-xe-may-GIVI-Campvivo_VN.jpg" width="630" /></div> <div><br /> <strong>Baga xe máy GIVI MR Monorack - 5391 </strong>là phụ kiện quan trọng sử dụng cùng thùng xe máy GIVI. Baga được sản xuất với dây chuyền công nghệ tiên tiến, kiểm tra chất lượng nghiêm ngặt, với tiêu chí an toàn đặt lên hàng đầu.<br /> <br /> Bảng chi tiết các dòng xe sử dụng <strong>Baga xe máy GIVI MR Monorack - 5391. Từng mẫu xe sẽ có baga kiểu dáng MR5 tương ứng.</strong><br />  </div> <p><strong>THÔNG TIN SẢN PHẨM</strong></p> <strong>THƯƠNG HIỆU</strong><strong>DÒNG XE</strong><strong>PHÂN KHỐI</strong><strong>MÃ BAGA</strong><strong>H</strong><strong>O</strong><strong>N</strong><strong>D</strong><strong>A</strong>GBO 7070ccMR5-GBOGBOJ 7070ccMR5-GBOJGB6 9090ccMR4-GB6EX5 100ccMR5-EX5EX5 CLASS 100ccMR5-EX5CLASS/WAVE100 WAVE 100 100ccMR5-EX5CLASS/WAVE100WAVE 100R/125X100